const top_sejuani = {
  champion: '세주아니',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 가렌의 (P)\'인내심\' 회복을 막기 위해 지속적으로 압박해야 해요. 가렌이 (Q)\'결정타\'로 달려오면 (Q)\'혹한의 맹습\'으로 먼저 공중으로 띄워 접근을 차단하세요. 짧은 교환 후에는 가렌이 (P)\'인내심\'으로 체력을 채우지 못하게 미니언과 함께 거리를 조절해요.', lv3: '가렌이 (Q)\'결정타\'를 사용해 침묵을 걸면 스킬을 쓸 수 없으니 주의해야 해요. 가렌이 (W)\'용기\'로 보호막을 켜면 (W)\'혹한의 서릿발\'로 스택을 쌓으며 기다렸다가 보호막이 사라진 뒤 (E)\'만년 서리\'를 사용하세요. (E)\'심판\'으로 회전하며 들어올 때는 (Q)\'혹한의 맹습\'을 맞춰 가렌의 움직임을 끊어주는 것이 좋아요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 체력이 낮을 때 매우 치명적이니 체력 관리에 신경 써야 해요. (R)\'빙하 감옥\'을 활용해 가렌을 묶어두면 아군 정글러와 함께 확실한 킬을 노릴 수 있어요. 가렌이 (Q)\'결정타\'로 빠르게 접근하는 것을 대비해 라인을 당겨 놓으며 정글러의 개입을 유도하세요.', item: '첫 코어 아이템으로 체력을 쌓으며 전투 지속력을 높여주는 강철심장을 가세요. 신발은 가렌의 평타 피해를 줄여주는 판금 장화를 추천해요. 판금 장화는 기본 공격 피해만 줄이고 (E)\'심판\' 같은 스킬 피해는 줄이지 못해요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복 효과를 억제해야 교환 후에 이득을 챙기기 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 무리하게 다가가지 마세요. (Q)\'혀어어어업상\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 체력 관리에 집중하며 스킬이 모일 때까지 버티세요. (P)\'혹한의 분노\'로 서리 갑옷의 추가 방어력이 있을 때만 짧게 딜교환을 시도하고 빠르게 빠지세요.', lv3: '(Q)\'혹한의 맹습\'으로 진입해 (W)\'혹한의 서릿발\'과 평타로 중첩을 쌓고 (E)\'만년 서리\'로 기절시키세요. 갱플랭크는 기절당하면 (W)\'괴혈병 치료\'를 쓸 수 없으니 귤을 먼저 쓰게 만든 뒤 몰아치는 것이 좋아요. (E)\'화약통\'이 발밑에서 터지면 둔화와 피해를 입으니 통을 빠르게 파괴하거나 거리를 벌리세요.', lv6: '갱플랭크가 (W)\'괴혈병 치료\'를 이미 쓴 직후에 (R)\'빙하 감옥\'을 맞히면 기절이 풀리지 않으니 정글러와 함께 진입해 연쇄 군중 제어를 노리세요. (R)\'포탄 세례\'가 떨어지는 구역은 둔화가 걸려 추격이 어려우니 장판 범위를 피해 이동하세요. (R)\'빙하 감옥\'의 긴 사거리를 활용해 갱플랭크가 (E)\'화약통\'을 설치하기 전에 먼저 묶어두는 것이 중요해요.', item: '판금 장화로 갱플랭크의 기본 공격 피해를 줄이세요. 첫 코어 아이템은 태양불꽃 방패를 가서 체력과 방어력을 챙기고 불사르기로 근접 전투 시 지속 피해를 입히세요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'괴혈병 치료\'의 체력 회복 효과를 감소시켜야 킬각을 잡기 편해요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화와 견제를 하며 (P)\'서비스 시간\'으로 체력을 회복하기 때문에 초반 소모전에 주의하세요. (Q)\'혹한의 맹습\' 사거리를 활용해 미니언을 챙기며 버티고, (P)\'혹한의 분노\'로 방어력을 높이며 받아내세요.', lv3: '그라가스가 (E)\'몸통 박치기\'로 공중으로 띄우려 할 때 거리를 조절하며 (Q)\'혹한의 맹습\'으로 빠르게 접근하세요. 그라가스의 (W)\'취중 분노\'가 켜진 상태에서는 받는 피해가 줄어드니, 그 효과가 끝난 뒤에 (E)\'만년 서리\'를 사용해 기절을 노리세요.', lv6: '(R)\'빙하 감옥\'으로 그라가스를 맞히면 강력한 기절을 걸 수 있지만, 그라가스의 (R)\'술통 폭발\'에 밀려나지 않도록 주의하세요. 정글러와 함께 (Q)\'혹한의 맹습\'과 (R)\'빙하 감옥\'을 연계하여 킬을 노리고, 라인을 빠르게 밀어 압박하세요.', item: '헤르메스의 발걸음은 마법 저항력을 주고 (Q)\'술통 굴리기\' 같은 둔화의 지속시간을 줄여줘요. 공중으로 띄우는 (E)\'몸통 박치기\'는 강인함으로 줄일 수 없으니 먼저 피하세요. 태양불꽃 방패를 첫 코어로 가서 지속적인 전투력을 높이세요.', spell: '점멸과 점화를 추천해요. (R)\'빙하 감옥\'으로 기절을 맞힌 뒤 점화를 사용하면 그라가스의 (P)\'서비스 시간\' 회복을 억제하며 킬을 낼 수 있어요.' },
    '그웬': { lv1: '1~2레벨에는 그웬의 (P)\'가위 난도질\'로 인한 추가 피해와 체력 회복을 조심하며 미니언을 챙기세요. (W)\'혹한의 서릿발\'로 서리 중첩을 쌓으면서도 무리한 교환은 피하세요.', lv3: '그웬이 (W)\'신성한 안개\'를 쓰면 안개 밖에서는 그웬을 대상으로 지정할 수 없어요. 하지만 (Q)\'혹한의 맹습\'과 (W)\'혹한의 서릿발\'은 대상 지정 스킬이 아니라서 그대로 맞힐 수 있어요. 안개 안에서는 그웬의 방어력과 마법 저항력이 오르니 안개 속에서 길게 싸우지 말고, 그웬이 안개를 떠날 때 (E)\'만년 서리\'를 노려요.', lv6: '(R)\'빙하 감옥\'을 맞춘 뒤 (E)\'만년 서리\'를 연계하면 강력한 기절을 선사할 수 있어요. 그웬의 (R)\'바느질\'은 둔화를 걸며 여러 번 날아오니 먼저 맞지 않도록 거리를 조절하세요. 정글러를 불러 함께 압박하세요.', item: '마법 저항력을 높여주는 헤르메스의 발걸음을 먼저 갖추세요. (P)\'가위 난도질\'의 체력 회복을 억제하기 위해 가시 갑옷을 준비하는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 그웬의 체력 회복을 줄여야 킬을 내기 편해요.' },
    '나르': { lv1: '나르의 (Q)\'부메랑 던지기\' 궤적을 피해 거리를 조절하세요. (W)\'혹한의 서릿발\'로 미니언을 정리하며 체력을 관리해요. 초반에는 무리하게 진입하기보다 서리 갑옷을 활용해 버티는 것이 좋아요.', lv3: '나르가 (E)\'폴짝\'으로 들어오면 (Q)\'혹한의 맹습\'으로 끊어주며 대응하세요. (Q)\'부메랑 던지기\'를 피했거나 나르가 부메랑을 받지 못했다면, 그 틈에 (W)\'혹한의 서릿발\'로 둔화를 걸고 서리 중첩을 쌓아 (E)\'만년 서리\'를 노리세요. 나르가 메가 나르로 변신해 (W)\'쿵쾅\'을 쓰기 전에 짧은 딜교환을 마쳐요.', lv6: '(R)\'빙하 감옥\'을 맞히면 (E)\'만년 서리\'와 연계해 킬각을 노려보세요. 메가 나르의 (R)\'나르!\'에 밀려 벽에 부딪히면 기절하니 벽 근처에서는 주의해야 해요. 정글러를 불러 라인을 압박하며 나르가 변신하기 전에 이득을 보세요.', item: '판금 장화와 강철심장을 준비하세요. 판금 장화는 나르의 기본 공격 피해를 줄여주고 강철심장은 체력을 높여줘요.', spell: '점멸과 점화를 추천해요. (R)\'빙하 감옥\'으로 적을 기절시킨 뒤 점화로 마무리 피해를 입히세요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 미니언을 먹으며 성장하니 초반에 막타를 못 먹게 방해해야 해요. (W)\'혹한의 서릿발\'로 미니언을 뒤로 밀어내어 나서스의 막타 기회를 줄이세요. (P)\'영혼의 포식자\' 때문에 길게 싸우면 나서스가 체력을 회복하니 짧게 교환하세요.', lv3: '나서스의 (W)\'쇠약\'은 대상 지정 둔화라 걸어서 피할 수 없어요. 대신 (P)\'혹한의 분노\' 서리 갑옷이 켜져 있으면 둔화에 면역이니, 서리 갑옷이 있을 때 (Q)\'혹한의 맹습\'으로 띄우고 (E)\'만년 서리\'로 기절을 연계해 딜교환을 하세요. (E)\'영혼의 불길\'이 깔린 곳은 방어력이 낮아지니 그 위에서 싸우지 마세요.', lv6: '나서스가 (R)\'사막의 분노\'를 켜면 체력과 방어력이 높아지니 정면 승부는 피하는 게 좋아요. (R)\'빙하 감옥\'을 맞춰 기절시킨 뒤 정글러를 불러서 함께 압박하세요. 라인을 내 포탑 쪽으로 당겨 두면 나서스가 (Q)\'흡수의 일격\'으로 미니언을 챙기려고 깊게 들어와야 하니 그때를 노리세요.', item: '판금 장화와 강철심장을 가세요. (Q)\'흡수의 일격\'의 물리 피해를 줄이고 체력을 높이기 위해서예요.', spell: '점멸과 점화예요. (P)\'영혼의 포식자\'의 체력 회복을 억제하기 위해서예요.' },
    '녹턴': { lv1: '녹턴은 (Q)\'황혼의 인도자\'를 맞히면 궤적 위에서 이동 속도와 공격력이 올라 따라붙으니 날아오는 칼날을 옆으로 피하세요. (P)\'그림자 칼날\'이 발동한 평타는 체력을 회복하니 평타 교환을 길게 하지 말고 (W)\'혹한의 서릿발\'로 짧게 치고 빠지세요.', lv3: '녹턴이 (W)\'어둠의 장막\'으로 기술을 막으려 할 때 보호막이 빠진 뒤에 (Q)\'혹한의 맹습\'을 사용하세요. (E)\'말할 수 없는 공포\'는 지속시간이 끝날 때까지 스킬 사거리 밖으로 벗어나지 않으면 공포가 걸리니 연결이 이어지는 동안 거리를 벌리세요. 공포 중에는 스킬을 쓸 수 없으니 걸리기 전에 (E)\'만년 서리\'를 먼저 쓰세요.', lv6: '녹턴이 (R)\'피해망상\'으로 돌격해 오면 (W)\'어둠의 장막\'을 썼는지 확인한 뒤 (R)\'빙하 감옥\'을 던져 기절시키세요. 시야가 줄어드는 동안은 라인을 관리하며 정글러의 개입을 유도하세요.', item: '판금 장화와 가시 갑옷을 선택해요. 녹턴의 기본 공격 피해를 줄이고 (P)\'그림자 칼날\'의 체력 회복을 억제하기에 좋아요.', spell: '점멸과 탈진을 사용하세요. 녹턴이 돌진하여 들어올 때 입히는 피해량을 감소시켜 생존을 도와요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩이 쌓일수록 평타와 스킬이 매우 강력해지니 1~2레벨 구간에 길게 싸우지 마세요. (Q)\'학살\' 도끼날에 맞으면 체력을 크게 회복하므로 도끼자루 범위에 붙거나 사거리 밖에서 (W)\'혹한의 서릿발\'로 견제하며 거리를 조절하세요.', lv3: '다리우스가 (E)\'포획\'으로 끌어당기려 할 때 (Q)\'혹한의 맹습\'으로 먼저 진입하여 위치를 잡는 것이 좋아요. 다리우스의 (W)\'마비의 일격\'이 닿으면 이동 속도가 줄어드니 주의하며 (W)\'혹한의 서릿발\'로 서리를 쌓아 (E)\'만년 서리\'를 준비하세요. 다리우스의 (E)\'포획\'이 빠진 타이밍에 (Q)\'혹한의 맹습\'과 (W)\'혹한의 서릿발\'을 연계해 딜교환을 시도하세요.', lv6: '다리우스의 (R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 많을수록 피해가 매우 커지니 체력이 낮을 때는 멀리 떨어져 있으세요. (R)\'빙하 감옥\'을 사용하여 다리우스를 묶은 뒤 아군 정글러를 불러 함께 압박하는 것이 효과적이에요. 다리우스가 (E)\'포획\'으로 끌어당긴 뒤 (R)\'녹서스의 단두대\'를 사용하지 못하도록 거리를 유지하며 대응하세요.', item: '다리우스의 평타 피해를 줄이기 위해 판금 장화를 먼저 구매하세요. 첫 코어 아이템으로는 방어력을 크게 높여주는 얼어붙은 심장을 추천해요.', spell: '점멸과 점화를 추천해요. 점화를 사용하면 다리우스의 (Q)\'학살\'로 인한 체력 회복 효과를 감소시킬 수 있어요.' },
    '라이즈': { lv1: '1~2레벨 구간에는 라이즈의 (Q)\'과부하\' 견제를 조심하며 거리를 유지하세요. (Q)\'과부하\'는 처음 맞는 적에게 적중하니 미니언 뒤에 서면 막을 수 있지만, (E)\'주문 전이\' 표식이 있으면 주변으로 튕겨요. (P)\'혹한의 분노\'로 방어력을 쌓으며 견제를 받아내세요.', lv3: '라이즈가 (E)\'주문 전이\'를 사용한 뒤 (W)\'룬 감옥\'으로 속박을 노릴 때 조심하세요. (W)\'룬 감옥\'이 빠졌다면 (Q)\'혹한의 맹습\'으로 돌진해 (W)\'혹한의 서릿발\'을 맞히며 딜교환을 하세요. (E)\'만년 서리\'를 활용해 기절까지 노리면 더 좋아요.', lv6: '라이즈가 (R)\'공간 왜곡\'으로 차원문을 열면 도망갈 수 있으니 라인을 깊게 밀지 마세요. (R)\'빙하 감옥\'으로 라이즈를 먼저 기절시킨 뒤 (Q)\'혹한의 맹습\'을 쓰면 킬을 따기 쉬워요. 정글러와 함께 라이즈의 합류를 압박하세요.', item: '헤르메스의 발걸음과 심연의 가면을 선택하세요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공해요. 심연의 가면은 마법 저항력과 체력을 높여줘요.', spell: '점멸과 점화를 추천해요. 라이즈의 체력을 빠르게 깎아 킬을 내는 데 도움을 줘요.' },
    '럼블': { lv1: '럼블이 (Q)\'화염방사기\'로 근접 거리에서 압박할 때는 거리를 유지하며 미니언을 챙기세요. (W)\'혹한의 서릿발\'을 사용하여 럼블의 움직임을 둔화시키며 서리 중첩을 쌓는 것에 집중해요. 1~2레벨 구간에는 럼블의 열기가 높아지기 전에 무리하게 싸우지 마세요.', lv3: '럼블이 (W)\'고철 방패\'를 사용하면 보호막이 유지되는 동안은 딜교환을 피하세요. (W)\'혹한의 서릿발\'로 서리 중첩을 충분히 쌓은 뒤에 (E)\'만년 서리\'를 사용하여 기절시키는 것이 중요해요. 럼블이 (E)\'전기 작살\'을 사용하여 마법 저항력을 낮추면 이후 교환이 더 아프게 느껴질 수 있어요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 사용해 화염의 벽을 만들면 그 장판을 피해 다니세요. (R)\'빙하 감옥\'을 맞힌 뒤에 (Q)\'혹한의 맹습\'으로 진입하여 적을 공중으로 띄우면 킬각을 잡기 쉬워요. 럼블의 궁극기는 정글러와 함께 대응하기 좋으니 라인을 밀 때 정글러의 위치를 꼭 확인하세요.', item: '첫 코어 아이템으로는 마법 저항력을 높여주는 심연의 가면을 추천해요. 신발은 럼블의 마법 피해를 줄이고 강인함을 얻기 위해 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 럼블이 (W)\'고철 방패\'로 버티는 상황에서 킬을 확실히 마무리하기 위해서예요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 초반에 강하게 압박해요. 1~2레벨에는 정면 충돌을 피하고 (W)\'혹한의 서릿발\'로 적을 둔화시키며 거리를 조절하세요. (P)\'혹한의 분노\'가 유지될 때만 짧게 딜교환을 하고 빠르게 빠지는 게 좋아요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 들어오면 (Q)\'혹한의 맹습\'으로 맞받아쳐 진입을 끊어내세요. 분노가 높을 때 (W)\'무자비한 포식자\' 기절에 걸리면 스킬을 쓸 수 없으니 주의하세요. (W)\'혹한의 서릿발\'로 서리를 쌓은 뒤 (E)\'만년 서리\'를 사용해 적을 얼리고 피해를 입히세요.', lv6: '(R)\'강신\'을 사용한 레넥톤은 체력이 늘어나고 분노가 계속 쌓이므로 정면 대결을 피하세요. (R)\'빙하 감옥\'으로 적을 기절시키고 주변을 둔화시키면 아군 정글러와 함께 공격하기 편해요. (E)\'자르고 토막내기\'의 재사용 돌격으로 빠져나가기 전에 (E)\'만년 서리\'로 발을 묶어 마무리하세요.', item: '태양불꽃 방패를 첫 코어로 가서 체력과 방어력을 챙기고 주변 피해를 입히세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'양떼 도륙\'의 체력 회복량을 깎아야 교전에서 밀리지 않아요.' },
    '렝가': { lv1: '수풀 근처로 접근하지 않도록 주의하며 거리를 유지하세요. 렝가가 (P)\'보이지 않는 포식자\'로 도약하며 (Q)\'포악함\'을 활용할 때 (P)\'혹한의 분노\'로 얻는 방어력을 활용해 피해를 받아내세요. (W)\'혹한의 서릿발\'은 렝가가 도약해 들어왔을 때 둔화를 거는 용도로 아껴 두세요.', lv3: '렝가의 야성 중첩이 낮을 때 (Q)\'혹한의 맹습\'으로 먼저 진입하여 (E)\'만년 서리\'를 적중시키세요. 렝가가 야성을 모두 모아 (W)\'전투의 포효\'로 군중 제어 효과를 해제하거나 (E)\'올가미 투척\'으로 속박을 걸지 못하도록 주의하며 싸워야 해요. (W)\'혹한의 서릿발\'을 섞어 서리 중첩을 빠르게 쌓는 것이 중요해요.', lv6: '렝가가 (R)\'사냥의 전율\'로 위장해 접근하면 도약해 붙는 순간 (R)\'빙하 감옥\'을 맞혀 기절시키고 반격하세요. 라인을 당겨서 수풀을 통한 기습을 방지하고 아군 정글러가 개입하기 좋은 구도를 만드세요. (E)\'만년 서리\'로 적을 묶어둔 뒤 아군과 함께 대응해야 해요.', item: '판금 장화와 가시 갑옷을 추천해요. 렝가의 기본 공격 피해를 줄이고 (W)\'전투의 포효\'를 통한 체력 회복을 억제하기 위해서예요.', spell: '점멸과 점화예요. 렝가의 (W)\'전투의 포효\'로 인한 체력 회복을 낮추고 킬각을 잡기 위해 필요해요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'로 빠르게 접근해 (P)\'룬 검\' 강화 평타를 섞으며 초반에 매우 강하게 압박해요. (W)\'혹한의 서릿발\'을 사용해 리븐을 둔화시키며 거리를 벌리고, (P)\'혹한의 분노\' 서리 갑옷이 있을 때만 딜교환을 짧게 받아내세요. 무리하게 쫓기보다 체력을 보존하며 경험치를 챙기는 것이 좋아요.', lv3: '리븐의 (W)\'기 폭발\' 기절이 빠진 것을 확인한 뒤에 (Q)\'혹한의 맹습\'으로 진입해 서리 중첩을 쌓으세요. (E)\'용맹\' 보호막이 켜져 있는 동안에는 (E)\'만년 서리\'를 사용하지 말고, 보호막이 사라지는 시점에 맞춰 기절시켜야 피해를 온전히 입힐 수 있어요. (Q)\'부러진 날개\'의 세 번째 타격에 공중으로 띄워지지 않도록 주의하며 끈질기게 붙으세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜고 진입할 때 (R)\'빙하 감옥\'을 던져 흐름을 끊고 기절시키세요. 이어서 (E)\'만년 서리\'로 기절 시간을 늘리면 그동안 리븐이 (E)\'용맹\'이나 (Q)\'부러진 날개\'로 빠져나갈 수 없어 정글러와 함께 처치하기 쉬워요. (R)\'추방자의 검\' 활성화 중에는 공격 사거리가 늘어나니 체력이 낮을 때는 거리 조절에 더 신경 쓰세요.', item: '판금 장화를 신고, 태양불꽃 방패를 첫 코어로 가서 높은 방어력과 체력으로 리븐의 폭발적인 피해를 버티세요. 주변 적에게 지속 피해를 입히며 라인 유지력도 높일 수 있어요.', spell: '점멸과 순간이동을 추천해요. 강력한 초반 압박을 견디며 라인 복귀와 운영을 통해 성장을 도모하는 것이 효율적이에요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'이 미니언을 꿰뚫고 지나가므로 뒤에 숨어도 피해를 입어요. (P)\'혹한의 분노\'를 유지해 마법 저항력을 챙기며 천천히 다가가세요. 무리한 진입보다는 (W)\'혹한의 서릿발\'로 미니언을 빠르게 정리하며 체력을 관리하세요.', lv3: '(W)\'서릿발\'에 속박되면 (Q)\'혹한의 맹습\' 같은 돌진은 못 쓰지만 (W)\'혹한의 서릿발\'은 쓸 수 있으니, 붙어 있다면 그대로 휘둘러 대응하세요. 리산드라가 (E)\'얼음갈퀴 길\'로 도망가기 전에 (E)\'만년 서리\'를 맞춰 기절시키는 것이 핵심이에요. 상대가 순간이동할 위치를 예측해 스킬을 사용하세요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 무적 상태가 되면 공격을 멈추고 기다리세요. (R)\'빙하 감옥\'을 먼저 맞힌 뒤 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'로 이어지는 연계로 킬각을 잡으세요. 리산드라의 군중 제어가 강력하니 정글러 호출 시 먼저 진입해 상대 스킬을 빼주세요.', item: '첫 코어로 대자연의 힘을 가서 체력과 마법 저항력을 높이고, 마법 피해를 여러 번 받으면 오르는 추가 마법 저항력으로 리산드라의 폭발적인 피해를 버티세요. 신발은 (W)\'서릿발\'의 속박과 (R)\'얼음 무덤\'의 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (W)\'서릿발\'의 속박을 즉시 풀고 (Q)\'혹한의 맹습\'으로 빠르게 접근해 역공을 가할 수 있어요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'과 (E)\'우주류 검술\' 덕분에 근접전이 매우 강해요. 1~2레벨에는 (W)\'혹한의 서릿발\'을 사용하여 거리를 조절하며 미니언을 챙기세요. 평타 사정권 안에서 오래 머물면 마스터 이의 공격을 감당하기 어려워요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용하여 대상 지정이 불가능해지면 무리하게 스킬을 쓰지 말고 기다려요. (Q)\'혹한의 맹습\'으로 마스터 이를 공중으로 띄우면 그가 (W)\'명상\'을 사용하는 것을 끊어낼 수 있어요. (W)\'혹한의 서릿발\'로 스택을 쌓은 뒤 (E)\'만년 서리\'로 기절을 시켜 딜교환을 하세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 켜면 둔화 효과에 면역이 되므로 (W)\'혹한의 서릿발\' 둔화는 효과가 나타나지 않아요. 하지만 (R)\'빙하 감옥\'이나 (E)\'만년 서리\'를 사용하여 마스터 이를 기절시키는 것은 가능해요. 마스터 이가 킬을 통해 지속시간을 늘리지 못하도록 정글러와 함께 압박하세요.', item: '첫 코어 아이템으로 가시 갑옷을 가고 신발은 판금 장화로 선택하세요. 가시 갑옷과 판금 장화로 마스터 이의 기본 공격에 대응하세요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복할 때 점화로 회복량을 줄여야 해요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸고 (P)\'마법 흡수\'로 체력을 회복해요. (Q)\'혹한의 맹습\'으로 진입할 때 상대의 밀쳐내기에 끊기지 않도록 주의하며 거리를 조절하세요. 초반에는 무리하게 붙기보다 미니언과 함께 딜교환하며 체력을 보존하세요.', lv3: '마오카이의 (W)\'뒤틀린 전진\'에 속박되면 (Q)\'혹한의 맹습\'으로는 빠져나갈 수 없지만 (W)\'혹한의 서릿발\'은 쓸 수 있으니, 붙은 마오카이에게 그대로 휘둘러 서리 중첩을 쌓으세요. 상대의 (Q)\'덤불 주먹\'에 밀려나기 전에 (Q)\'혹한의 맹습\'으로 띄우고 (E)\'만년 서리\'로 기절시켜 딜교환을 마무리하세요. (E)\'묘목 던지기\'가 깔린 수풀은 둔화 때문에 위험하니 피해서 이동하세요.', lv6: '(R)\'대자연의 마수\' 벽이 다가오면 옆으로 빠르게 피해 속박되는 것을 막으세요. (R)\'빙하 감옥\'으로 먼저 상대를 얼린 뒤 (Q)\'혹한의 맹습\'으로 진입하면 안정적으로 킬각을 잡을 수 있어요. 마오카이가 (Q)\'덤불 주먹\'을 헛쳤을 때 (E)\'만년 서리\'로 기절을 연계해 제압하세요.', item: '끝없는 절망을 첫 코어로 선택해 지속적인 체력 회복과 탱킹력을 챙기세요. 신발은 마법 저항력을 높이고 속박과 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 마오카이가 (P)\'마법 흡수\'로 계속 체력을 회복하므로 점화의 치유 감소 효과로 이를 억제하며 처치하세요.' },
    '말자하': { lv1: '말자하가 (P)\'공허 태세\'를 유지하면 피해가 줄어드니 (W)\'혹한의 서릿발\'로 먼저 공격해 보호를 벗겨야 해요. (Q)\'공허의 부름\' 침묵을 맞으면 스킬 사용이 막히니 사거리를 잘 조절하며 파밍하세요.', lv3: '말자하가 (W)\'공허의 무리\'를 소환해 공허충이 몰려오면 (Q)\'혹한의 맹습\'으로 빠르게 접근해 맞붙으세요. (E)\'재앙의 환상\'이 걸린 상태에서 (Q)\'공허의 부름\'까지 맞으면 위험하니 (W)\'혹한의 서릿발\'로 서리를 쌓으며 대응하세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 말자하가 궁극기를 쓰기 전에 (R)\'빙하 감옥\'을 먼저 맞히는 것이 중요해요. 말자하가 궁극기로 제압을 걸면 움직일 수 없으니 정글러의 개입을 통해 대처하세요.', item: '헤르메스의 발걸음으로 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템은 마법 저항력을 제공하는 심연의 가면이 좋아요.', spell: '점멸과 점화를 추천해요. 제압은 정화로 풀 수 없으니 점화로 말자하의 체력을 깎아 킬각을 만드세요.' },
    '말파이트': { lv1: '말파이트는 대상 지정 스킬인 (Q)\'지진의 파편\'으로 체력을 깎으며 이동 속도를 훔쳐요. (P)\'화강암 방패\'가 활성화된 상태에서는 평타 교환이 비효율적이니 방패가 사라진 뒤에 (W)\'혹한의 서릿발\'로 짧게 딜교환하세요. 첫 웨이브부터 무리하게 붙기보다 상대의 스킬 쿨타임을 확인하며 거리를 유지하세요.', lv3: '(E)\'지면 강타\'를 맞으면 공격 속도가 감소해 (E)\'만년 서리\' 스택을 쌓기 어려우니 주의하세요. (Q)\'혹한의 맹습\'으로 빠르게 진입한 뒤 (W)\'혹한의 서릿발\'로 적을 둔화시키며 스택을 쌓아 기절시키는 구도를 만드세요. (W)\'천둥소리\'를 켠 말파이트의 평타는 여진 피해를 주니 정면에서 오래 맞서지 마세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 도중에 막을 수 없고 맞으면 공중에 떠서 아무것도 못 해요. 정글러가 근처에 있다면 말파이트의 돌진 거리 밖에서 대기하다가 (R)\'빙하 감옥\'으로 먼저 적을 묶어 기습하세요. (R)\'멈출 수 없는 힘\'이 빠진 이후에는 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\' 콤보로 계속 압박하며 라인을 밀어 넣으세요.', item: '마법 피해를 주로 주는 상대이므로 마법 저항력과 강인함이 있는 헤르메스의 발걸음을 신으세요. 체력을 높이고 전투 중 체력을 회복하는 끝없는 절망을 첫 코어로 가야 (Q)\'지진의 파편\' 견제를 버티며 싸울 수 있어요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인에 빠르게 복귀하고, 점멸로 (R)\'멈출 수 없는 힘\'의 돌진 경로에서 벗어날 수 있어요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 범위 안의 모든 적에게 들어가고 단일 대상에게 맞으면 피해가 커지니 미니언 뒤에 숨기보다 사거리 밖에서 움직이세요. (P)\'암흑 탄생\' 오라가 켜지면 주변 피해가 계속 들어오니 오래 붙어 있지 말고 빠르게 빠지세요. (W)\'혹한의 서릿발\'로 적을 둔화시키며 짧게 교환하고 거리를 조절하세요.', lv3: '(E)\'죽음의 손아귀\'에 끌려가면 모데카이저의 콤보에 노출되니 사거리 밖에서 움직이며 스킬을 먼저 빼게 하세요. (Q)\'혹한의 맹습\'으로 진입한 뒤 (W)\'혹한의 서릿발\'을 휘둘러 (E)\'만년 서리\' 기절을 빠르게 노리세요. (W)\'불멸\' 보호막이 활성화된 상태에서는 딜교환을 길게 하지 말고 잠시 물러나세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 수은 장식띠로도 풀 수 없고 빠져나올 방법이 없으니 체력이 낮을 때 끌려가지 않게 주의하세요. (R)\'빙하 감옥\'을 먼저 맞혀 적을 기절시킨 뒤 정글러와 함께 빠르게 처리하는 구도를 만드세요. 차원 안에서는 최대한 버티며 상대의 핵심 스킬이 빠질 때까지 기다리세요.', item: '첫 코어로 대자연의 힘을 가서 체력과 마법 저항력을 높이고, 마법 피해를 여러 번 받으면 오르는 추가 마법 저항력으로 버티세요. 신발은 마법 저항력과 강인함이 붙은 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (W)\'불멸\'의 체력 회복을 억제해야 킬각을 잡기 쉬워요.' },
    '문도박사': { lv1: '문도 박사가 (Q)\'오염된 뼈톱\'을 던지면 처음 맞는 적에게 맞으니 미니언 뒤에 서서 뼈톱이 챔피언에게 닿지 않게 하세요. (P)\'가고 싶은 데로 간다\'는 처음 적중하는 기절 같은 이동 불가 효과에 저항하니, 이 효과가 쓰인 뒤 재사용 대기 중일 때 (E)\'만년 서리\'를 맞히세요. 초반에는 무리하게 딜교환을 하기보다 (W)\'혹한의 서릿발\'로 견제하며 체력을 관리하세요.', lv3: '(W)\'혹한의 서릿발\'을 활용해 서리 중첩을 쌓으며 (E)\'만년 서리\'를 준비하세요. 문도 박사가 (W)\'심장 전기 충격\'으로 피해를 저장하며 버틸 때는 오래 붙어 있지 말고 (Q)\'혹한의 맹습\'으로 진입해 짧게 교환하세요. 문도 박사가 (Q)\'오염된 뼈톱\'을 맞혀 체력을 회복하지 못하도록 스킬을 신중하게 사용하세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 체력 회복과 이동 속도가 크게 늘어나니 무리하게 추격하지 마세요. (R)\'빙하 감옥\'은 (P)\'가고 싶은 데로 간다\'가 재사용 대기 중인지 확인하고 사용하며, 아군 정글러의 개입을 유도하여 함께 압박하세요. 문도 박사의 체력이 낮아졌을 때 궁극기로 기절시킨 뒤 라인을 밀어넣고 다른 곳을 지원하세요.', item: '첫 코어로 가시 갑옷을 가서 문도 박사의 기본 공격과 체력 회복을 억제하세요. 신발은 문도 박사의 (Q)\'오염된 뼈톱\'과 (W)\'심장 전기 충격\' 같은 마법 피해를 줄이기 위해 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과를 활용해야 문도 박사의 (R)\'최대 투여량\'과 (Q)\'오염된 뼈톱\' 회복을 억제하며 킬을 낼 수 있어요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'로 미니언을 관통하며 견제하니 옆으로 움직여서 피하거나 위치를 조절해야 해요. 첫 웨이브 구간에서는 무리하게 붙기보다 체력을 보존하며 (Q)\'혹한의 맹습\'을 사용할 타이밍을 기다리세요.', lv3: '바루스가 (W)\'역병 화살\'로 쌓은 중첩을 다른 스킬로 터뜨리지 못하게 주의하며 거리를 벌리세요. (E)\'퍼붓는 화살\'이 깔린 지면은 이동 속도를 늦추고 회복을 줄이니 그 위를 피하며 (Q)\'혹한의 맹습\'으로 접근하세요. (W)\'혹한의 서릿발\'로 서리 중첩을 쌓으며 압박하세요.', lv6: '바루스의 (R)\'부패의 사슬\'에 맞아 속박되면 (Q)\'혹한의 맹습\' 같은 돌진을 쓸 수 없으니 촉수가 날아오는 방향을 보고 비켜서세요. 바루스가 궁극기를 쓴 뒤에 (R)\'빙하 감옥\'을 맞혀 기절시키고 정글러와 함께 킬을 노리세요.', item: '바루스의 기본 공격 피해를 줄이기 위해 판금 장화를 선택하세요. 첫 코어 아이템은 체력과 방어력을 높여주는 태양불꽃 방패를 추천해요.', spell: '점멸과 점화를 추천해요. (Q)\'혹한의 맹습\'으로 진입할 때 점멸을 활용하고 점화로 마무리 피해를 높이세요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 벌리며 평타를 치고 (W)\'은화살\'로 최대 체력 비례 고정 피해를 입힐 수 있어요. 1~2레벨에는 베인의 사거리 안에서 무리하게 맞대결하지 말고 미니언을 받아먹으며 버티세요. 벽 근처에서 싸우면 (E)\'선고\'를 맞아 기절할 수 있으니 탁 트인 곳에서 움직여요.', lv3: '베인의 (Q)\'구르기\'가 빠진 것을 확인한 뒤에 (Q)\'혹한의 맹습\'으로 진입하는 것이 좋아요. (W)\'혹한의 서릿발\'로 서리를 쌓고 (E)\'만년 서리\'를 맞히면 베인의 움직임을 묶을 수 있어요. 베인이 (E)\'선고\'를 사용해 뒤로 밀려나지 않도록 거리를 조절하며 스킬을 맞히세요.', lv6: '베인이 (R)\'결전의 시간\'을 켠 뒤 (Q)\'구르기\'를 쓰면 잠시 투명 상태가 되니 그 순간에는 위치를 놓치기 쉬워요. 투명이 풀린 순간 (R)\'빙하 감옥\'을 맞혀 기절시킨 뒤 전투를 시작하세요. 라인을 빠르게 밀어 넣고 정글러를 호출하여 베인이 (Q)\'구르기\'로 도망치지 못하게 잡는 것이 중요해요.', item: '판금 장화와 강철심장을 선택하세요. 베인의 기본 공격 피해를 견디고 체력을 높이는 데 도움을 줘요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'를 사용하여 거리를 벌리더라도 점화로 마무리 피해를 입힐 수 있어요.' },
    '볼리베어': { lv1: '1~2레벨에는 볼리베어가 (Q)\'번개 강타\'로 달려와 기절을 걸며 강하게 압박해요. (Q)\'혹한의 맹습\'으로 먼저 진입하기보다 볼리베어의 (Q)\'번개 강타\'가 빠진 뒤에 거리를 좁히며 대응하세요. (P)\'혹한의 분노\' 효과를 활용해 방어력을 높이며 버티는 것이 중요해요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 표식을 남기고 체력을 회복하려 할 때 (Q)\'혹한의 맹습\'으로 끊어주는 것이 좋아요. 볼리베어가 (E)\'천공 분열\'을 사용하여 보호막을 얻기 전에 (E)\'만년 서리\'를 맞춰서 최대한의 CC를 연계하세요. 볼리베어의 스킬이 빠진 타이밍에 (W)\'혹한의 서릿발\'로 둔화를 걸며 딜교환을 하세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'를 사용해 포탑을 비활성화하며 다이브를 시도할 수 있으니 주의하세요. 볼리베어가 도약하기 전에 (R)\'빙하 감옥\'을 먼저 맞히거나, 상황에 따라 착지한 직후에 던져 기절시키세요. 정글러를 부를 때 (R)\'빙하 감옥\'으로 볼리베어를 묶어두면 효과적이에요.', item: '첫 코어로 태양불꽃 방패를 가서 체력과 방어력을 챙기세요. 신발은 볼리베어의 마법 피해와 군중 제어 효과를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 볼리베어가 (W)\'광란의 상처\'로 체력을 회복하는 것을 점화로 억제하며 킬각을 잡으세요.' },
    '블라디미르': { lv1: '블라디미르가 (Q)\'수혈\'로 체력을 채우며 견제할 때 거리를 조절하며 파밍에 집중하세요. (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤로 피할 수 없으니 사거리 안에 오래 머물지 마세요. (W)\'혹한의 서릿발\'을 사용해 미니언을 정리하며 라인을 안정적으로 관리하세요.', lv3: '블라디미르가 (W)\'피의 웅덩이\'를 사용하면 대상으로 지정할 수 없으니 스킬을 낭비하지 마세요. (E)\'선혈의 파도\'는 미니언에 가로막힐 수 있으니 미니언 뒤에서 위치를 잡으세요. (Q)\'혹한의 맹습\'으로 진입한 뒤 (W)\'혹한의 서릿발\'을 맞히고 (E)\'만년 서리\'로 기절을 시도하세요.', lv6: '블라디미르가 (R)\'혈사병\'을 사용해 받는 피해를 늘리면 즉시 거리를 벌려야 해요. (R)\'빙하 감옥\'으로 블라디미르를 기절시키고 (Q)\'혹한의 맹습\'을 이어가 킬각을 보세요. 상대가 성장할수록 강해지므로 정글러를 불러 압박하거나 라인을 빠르게 밀어 넣으세요.', item: '마법 피해를 줄이기 위해 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템은 마법 저항력을 높여주는 심연의 가면을 추천해요.', spell: '점멸과 점화를 추천해요. 블라디미르가 (Q)\'수혈\'로 체력을 회복하므로 점화로 회복량을 줄여야 해요.' },
    '뽀삐': { lv1: '뽀삐는 (P)\'강철의 외교관\'으로 보호막을 얻으며 (Q)\'망치 강타\'로 둔화를 걸어요. (W)\'혹한의 서릿발\'을 활용해 뽀삐가 둔화 지대를 만들기 전에 짧게 교환하세요. 뽀삐가 방패를 주워 보호막을 얻기 전에 딜교환을 시도하는 것이 좋아요.', lv3: '뽀삐의 (W)\'굳건한 태세\'는 (Q)\'혹한의 맹습\' 같은 돌진기를 막아내니 스킬이 빠진 뒤에 진입하세요. (W)\'혹한의 서릿발\'로 서리를 쌓아 (E)\'만년 서리\'를 적중시키는 것이 중요해요. 뽀삐의 (E)\'용감한 돌진\'이 벽에 부딪혀 기절을 유발하지 않도록 벽에서 떨어져서 싸우세요.', lv6: '뽀삐의 (R)\'수호자의 심판\'에 맞으면 멀리 날아가니 집중하는 동안 범위에서 벗어나세요. (R)\'빙하 감옥\'을 사용하여 뽀삐를 묶고 아군과 함께 교전하면 좋아요. 뽀삐가 궁극기를 사용하면 거리가 벌어지니 라인을 밀어 넣어 압박하세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 뽀삐의 물리 피해를 줄이고 전투 중에 지속적인 피해를 입힐 수 있어요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐에게 지속 고정 피해를 입혀 아군과 함께 킬을 만들어내기 좋아요.' },
    '사이온': { lv1: '사이온이 (Q)\'대량 학살 강타\'를 충전할 때는 옆으로 비켜서서 기절을 피하세요. (E)\'학살자의 포효\'는 미니언을 밀어내며 관통하므로 일직선상에 서 있지 마세요. 상대가 스킬을 쓰는 타이밍에 맞춰 (Q)\'혹한의 맹습\'을 사용할 준비를 하세요.', lv3: '사이온이 (W)\'영혼의 용광로\' 보호막을 사용하면 피해가 흡수되니 (W)\'혹한의 서릿발\'로 서리 중첩을 먼저 쌓으며 기다리세요. (Q)\'대량 학살 강타\'가 끝나는 타이밍에 맞춰 (Q)\'혹한의 맹습\'으로 진입하여 싸우세요. 보호막이 사라진 뒤에 (E)\'만년 서리\'를 맞히며 딜교환을 하세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진하면 경로를 예측해 옆으로 비켜서세요. 돌진이 끝난 뒤 (R)\'빙하 감옥\'으로 사이온을 묶고 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'를 연계하세요. 사이온은 (P)\'영광스러운 죽음\'으로 다시 살아날 수 있으니 주의하세요.', item: '첫 코어로 체력을 높여주는 강철심장을 가세요. 신발은 방어력을 높여주는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 라인 복귀를 위해 순간이동이 필요하며 (R)\'빙하 감옥\'을 맞히기 위해 점멸을 사용하세요.' },
    '사일러스': { lv1: '1~2레벨에는 사일러스의 (Q)\'사슬 후려치기\' 견제를 조심하며 미니언을 챙기세요. 사일러스가 (P)\'페트리사이트 폭발\' 강화 평타로 압박할 때는 (W)\'혹한의 서릿발\'로 둔화를 걸며 맞대응하세요. (Q)\'혹한의 맹습\'은 사일러스가 스킬을 뺀 직후 진입하는 용도로 아껴 두세요.', lv3: '사일러스가 (W)\'국왕시해자\'로 돌진하며 체력을 회복하려고 하면 (Q)\'혹한의 맹습\'으로 흐름을 끊으세요. 사일러스의 (E)\'도주 / 억압\' 사슬이 날아올 때 옆으로 비켜서서 공중으로 뜨는 것을 피해야 해요. (W)\'혹한의 서릿발\'로 서리를 쌓은 뒤 (E)\'만년 서리\'를 맞히는 타이밍을 노리세요.', lv6: '사일러스가 (R)\'강탈\'로 (R)\'빙하 감옥\'을 가져가면 역으로 기절당할 수 있으니 조심하세요. 사일러스의 (W)\'국왕시해자\' 회복이 빠진 것을 확인하고 (R)\'빙하 감옥\'을 사용하여 묶으세요. 정글러가 근처에 있다면 (E)\'만년 서리\'로 적을 묶어 아군과 함께 공격하세요.', item: '헤르메스의 발걸음을 가서 사일러스의 마법 피해를 줄이고 강인함을 얻으세요. 첫 코어 아이템은 체력과 마법 저항력을 주는 심연의 가면을 선택하세요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복할 때 점화로 회복 효과를 줄여 주세요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'으로 이동 속도를 높여 달려들고, 다음 두 번의 기본 공격으로 큰 피해를 입히니 조심하세요. (W)\'혹한의 서릿발\'은 미니언 정리보다 세트에게 맞혀 서리 중첩을 쌓는 데 쓰세요. 세트의 초반 교전이 강한 구간이니 맞붙지 말고 평타 사거리 밖으로 거리를 유지하세요.', lv3: '세트의 (E)\'안면 강타\'는 양옆에 적이 하나씩 있으면 끌어당겨 기절시키고 한쪽에만 있으면 둔화만 거니, 세트가 나와 우리 미니언 사이에 서지 않도록 위치를 잡으세요. 세트의 (W)\'강펀치\' 보호막이 켜진 동안은 딜교환을 피하고 사라진 뒤 (Q)\'혹한의 맹습\'으로 진입하세요. (W)\'혹한의 서릿발\'로 둔화를 걸어 세트의 접근을 늦추며 스택을 쌓는 것이 좋아요.', lv6: '세트가 (R)\'대미 장식\'으로 나를 붙잡아 제압한 채 내리꽂을 수 있으니 세트가 붙기 전에 위치를 조심하세요. (R)\'빙하 감옥\'을 맞힌 뒤 (Q)\'혹한의 맹습\'으로 진입하여 (E)\'만년 서리\'까지 연계하면 세트를 확실히 묶어둘 수 있어요. 세트가 (R)\'대미 장식\'을 쓰기 전에 먼저 기절을 걸어 흐름을 끊는 것이 좋아요.', item: '판금 장화와 얼어붙은 심장을 선택하세요. 판금 장화는 세트의 기본 공격 피해를 줄여주고 얼어붙은 심장은 방어력과 스킬 가속을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화는 세트의 (P)\'투기장의 투지\'를 통한 체력 회복 효과를 감소시켜 킬각을 잡는 데 도움을 줘요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주고 (P)\'기 보호막\'을 얻어서 초반 교환이 까다로워요. (W)\'혹한의 서릿발\'로 적절히 거리를 벌리며 쉔이 평타 강화 타이밍에 진입하지 못하게 하세요. (P)\'혹한의 분노\'로 방어력을 높인 상태에서 쉔의 공격을 받아내며 천천히 압박하세요.', lv3: '(E)\'그림자 돌진\'에 도발되면 스킬을 쓸 수 없으니 쉔이 돌진하기 전에 (Q)\'혹한의 맹습\'으로 먼저 띄워 흐름을 끊으세요. (W)\'의지의 결계\'가 켜진 동안은 평타가 막혀 (E)\'만년 서리\' 중첩을 쌓기 어려우니 결계가 끝난 뒤에 딜교환을 하세요. (W)\'혹한의 서릿발\'로 둔화를 걸고 빠르게 중첩을 쌓아 (E)\'만년 서리\'로 기절시키는 것이 중요해요.', lv6: '(R)\'단결된 의지\'로 쉔이 아군에게 합류하면 빠르게 라인을 밀어 포탑 피해를 입히세요. 쉔이 다시 돌아왔을 때 (R)\'빙하 감옥\'으로 먼저 기절시킨 뒤 (Q)\'혹한의 맹습\'으로 진입해 킬각을 잡으세요. (P)\'기 보호막\'이 생성되기 전이나 보호막이 사라진 직후에 강력한 스킬 연계를 넣는 것이 포인트예요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 헤르메스의 발걸음은 (E)\'그림자 돌진\'의 도발 시간을 줄여주고 태양불꽃 방패는 체력과 방어력을 높이며 지속 피해를 줘요.', spell: '점멸과 순간이동을 추천해요. 쉔이 (R)\'단결된 의지\'로 다른 라인에 개입할 때 순간이동으로 빠르게 복귀하거나 합류하세요.' },
    '쉬바나': { lv1: '쉬바나의 (E)\'용암 분출\' 사거리에 닿지 않도록 주의하며 미니언을 챙기세요. (W)\'혹한의 서릿발\'을 사용해 상대의 접근을 견제하고 서리 중첩을 쌓으며 거리 조절을 해요. 첫 웨이브에서는 무리한 진입보다 상대의 스킬 쿨타임을 확인하며 신중하게 행동하세요.', lv3: '(Q)\'혹한의 맹습\'으로 빠르게 진입해 (W)\'혹한의 서릿발\'과 평타로 서리 중첩을 쌓고 (E)\'만년 서리\'로 기절시키세요. 쉬바나가 (E)\'용암 분출\'을 사용해 둔화를 걸려 하면 옆으로 움직여 피하는 것이 중요해요. (W)\'지옥불 방패\'의 보호막이 사라질 때까지 기다렸다가 본격적인 딜교환을 시도하세요.', lv6: '쉬바나의 (R)\'용의 강림\'은 저지 불가 상태로 날아오며 경로의 적을 달아나게 하니, 도약 중에 막으려 하지 말고 착지한 뒤 (R)\'빙하 감옥\'을 맞혀 기절시키세요. 용 형상일 때의 강력한 피해와 (W)\'지옥불 방패\'의 체력 회복을 주의하며 짧은 딜교환을 반복해요. (E)\'만년 서리\'를 적절히 섞어 상대가 쉽게 빠져나가지 못하게 묶어두고 정글러의 합류를 유도하세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 구매하세요. 상대의 마법 피해를 줄이고 강인함으로 둔화 지속시간을 줄이며, 체력과 방어력을 높여 지속 싸움에서 앞서기 위해서예요.', spell: '점멸과 점화. 쉬바나가 용 형상일 때 (W)\'지옥불 방패\' 폭발로 회복하는 체력을 줄이고 확실하게 마무리하기 위해서예요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 계속 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. 무작정 진입하기보다 (P)\'혹한의 분노\' 서리 갑옷을 유지해 추가 마법 저항력으로 견제를 받아내세요. (W)\'혹한의 서릿발\'로 미니언을 밀어내며 적절한 거리를 유지하는 게 중요해요.', lv3: '(E)\'속박명령\'의 파동이 돌아올 때 옆으로 비켜서서 속박을 피하는 것이 핵심이에요. 상대가 스킬을 낭비했다면 (Q)\'혹한의 맹습\'으로 빠르게 붙어 (W)\'혹한의 서릿발\'로 서리 중첩을 쌓고 (E)\'만년 서리\'로 기절시키세요. (W)\'제국의 눈\'의 둔화에 걸리면 진입이 어려우니 주의하세요.', lv6: '(R)\'악의 승천\'을 사용한 스웨인은 주변 적의 체력을 계속 흡수하니 너무 오래 붙어 있지 마세요. 변신하기 전에 (R)\'빙하 감옥\'으로 기절시켜 흐름을 끊거나 정글러를 불러 함께 처리하세요. 변신 상태의 스웨인은 끈질기니 (E)\'만년 서리\'와 평타로 짧게 딜교환하고 빠지세요.', item: '심연의 가면과 헤르메스의 발걸음을 추천해요. 마법 저항력과 체력을 높여 스웨인의 마법 피해를 견디고 강인함으로 속박 지속시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. 스웨인이 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'로 체력을 회복하는 것을 점화로 억제해야 해요.' },
    '스카너': { lv1: '스카너의 (Q)\'부서진 대지/지반 돌출\' 투사체가 날아오지 않게 거리를 조절하며 파밍해요. (W)\'혹한의 서릿발\'을 사용하여 미니언을 정리하며 성장에 집중하세요. 초반에는 스카너의 공격에 휘말리지 않도록 주의하며 대응해요.', lv3: '벽 근처에서는 스카너의 (E)\'이쉬탈의 격돌\'에 끌려가 기절하지 않도록 조심하세요. 스카너가 (W)\'대지의 수호자\'로 보호막을 얻었을 때는 무리한 딜교환을 피해요. (Q)\'혹한의 맹습\'을 사용하여 적절한 타이밍에 진입하며 서리를 쌓으세요.', lv6: '스카너가 (R)\'꿰뚫기\'로 제압하려 할 때를 대비해 위치를 잘 잡아야 해요. (R)\'빙하 감옥\'을 적중시켜 스카너의 움직임을 멈추고 킬 기회를 만들어보세요. 정글러가 올 때 (R)\'빙하 감옥\'의 기절을 활용해 확정적인 호응을 유도해요.', item: '판금 장화와 얼어붙은 심장을 가요. 스카너의 물리 피해를 줄이고 방어력을 높이기 위해서예요.', spell: '점멸과 점화를 사용해요. (R)\'빙하 감옥\'으로 묶은 뒤 점화의 고정 피해로 스카너의 체력을 깎으며 마무리해요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 독구름을 남겨 지속 피해를 주고 라인을 밀어내요. 독구름 위에서 싸우지 말고 (W)\'혹한의 서릿발\'로 적절히 거리를 벌리며 미니언을 챙기세요. 신지드가 무리하게 다가올 때 평타로 대응하며 체력 관리에 집중하세요.', lv3: '(W)\'초강력 접착제\'가 깔린 곳에서는 (Q)\'혹한의 맹습\'을 사용할 수 없으니 주의하세요. (E)\'던져넘기기\'에 던져져 접착제 위에 떨어지면 속박되니 접착제 근처에서 신지드에게 붙잡히지 않게 거리를 조절하세요. 접착제가 빠진 것을 확인한 뒤 (Q)\'혹한의 맹습\'으로 진입해 (E)\'만년 서리\'로 기절을 시키세요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 이동 속도가 빨라지고 전투 능력이 올라가니 정면 충돌을 피하세요. (R)\'빙하 감옥\'으로 신지드를 멀리서 기절시키고 아군 정글러의 개입을 유도해 빠르게 처리하세요. 신지드가 라인을 밀 때 (Q)\'혹한의 맹습\'과 연계해 킬각을 잡으세요.', item: '태양불꽃 방패를 첫 코어로 선택해 체력과 방어력을 높이고 주변 피해를 입히세요. 신발은 (Q)\'맹독의 자취\' 마법 피해와 (W)\'초강력 접착제\'의 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 강력한 고정 피해를 더해 체력이 낮은 신지드를 확실하게 마무리하세요.' },
    '신짜오': { lv1: '신짜오는 (Q)\'삼조격\'의 세 번째 공격으로 에어본을 일으키며 강력하게 압박해요. (W)\'혹한의 서릿발\'로 둔화를 걸며 거리를 유지하고 서리 갑옷이 생길 때까지 기다리세요. 미니언을 안전하게 챙기며 초반 교전을 피하는 것이 좋아요.', lv3: '(Q)\'혹한의 맹습\'으로 진입한 뒤 (E)\'만년 서리\'를 연계하여 신짜오를 묶어주세요. 신짜오가 (W)\'풍전참뢰\'를 쓰고 다가오면 (W)\'혹한의 서릿발\'로 대응하며 딜교환을 해요. 상대의 (E)\'무쌍돌격\' 사거리에 들어가지 않도록 주의하세요.', lv6: '(R)\'빙하 감옥\'을 사용해 신짜오가 (R)\'현월수호\'를 켜고 피해를 무시하기 전에 기절시켜야 해요. 정글러의 개입을 유도하거나 라인을 당겨서 상대의 진입을 받아내세요. 궁극기 사용 후에는 신중하게 후속 행동을 결정해요.', item: '판금 장화와 강철의 솔라리 펜던트를 선택해요. 신짜오의 기본 공격 피해를 줄이고 아군을 보호하기 위해서예요.', spell: '점멸과 점화. 신짜오의 체력 회복을 줄이며 확실하게 킬을 내기 위해서예요.' },
    '아이번': { lv1: '아이번이 (Q)\'덩굴뿌리\'로 거리를 벌리며 견제할 때 무리하게 들어가지 마세요. (W)\'혹한의 서릿발\'을 활용해 미니언을 밀어내며 적과의 거리를 조절하며 버텨야 해요. 초반에는 체력 관리에 집중하며 다음 단계의 교전을 준비하세요.', lv3: '아이번의 (Q)\'덩굴뿌리\'가 빠진 타이밍을 노려 (Q)\'혹한의 맹습\'으로 진입하는 것이 좋아요. 진입 후에는 (W)\'혹한의 서릿발\'을 계속 맞춰서 서리 중첩을 쌓아야 해요. 상대가 (E)\'보호의 씨앗\'으로 보호막을 만들기 전에 빠르게 압박하세요.', lv6: '(R)\'빙하 감옥\'을 적중시키면 강력한 교전이 가능해요. 다만 아이번이 (R)\'데이지!\'를 소환하면 데이지가 같은 챔피언을 세 번 공격할 때 공중으로 띄우니 주의하며 싸워야 해요. 정글러를 불러서 데이지가 사라진 뒤 함께 몰아붙이면 이득을 챙길 수 있어요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 추천해요. 헤르메스의 발걸음으로 아이번의 마법 피해와 (Q)\'덩굴뿌리\' 속박 시간을 줄이고, 태양불꽃 방패로 체력과 방어력을 챙기며 주변에 지속 피해를 입히세요.', spell: '점멸과 점화. (Q)\'혹한의 맹습\'과 함께 점멸을 사용하여 적을 갑작스럽게 띄우기 위해서예요.' },
    '아지르': { lv1: '아지르가 (Q)\'사막의 맹습\'으로 견제할 때 미니언과 함께 무리하지 않게 받아내세요. (P)\'혹한의 분노\'로 서리 갑옷을 활성화하며 방어력을 높이는 것이 좋아요. 거리를 조절하며 안정적으로 경험치를 챙기세요.', lv3: '(Q)\'혹한의 맹습\'으로 진입하며 아지르의 (E)\'신기루\' 사용을 유도하는 것이 중요해요. (W)\'혹한의 서릿발\'로 서리를 쌓은 뒤 (E)\'만년 서리\'를 적중시켜 딜교환을 시도해요. 아지르가 (W)\'일어나라!\'로 병사를 소환해 공격할 때 타이밍을 잘 맞춰야 해요.', lv6: '(R)\'빙하 감옥\'에 기절한 아지르는 (R)\'황제의 진영\'을 쓸 수 없으니 그동안 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'로 몰아치세요. 아지르가 궁극기로 나를 밀어내 거리를 벌릴 수 있으니 정글러와 함께 압박하며 킬각을 잡아야 해요. 라인을 관리하며 아지르의 움직임을 제한하세요.', item: '헤르메스의 발걸음과 심연의 가면을 추천해요. 아지르의 마법 피해를 줄이고 체력과 마법 저항력을 얻기 위해서예요.', spell: '점멸과 점화. (R)\'빙하 감옥\'을 맞힌 뒤 점멸로 순식간에 접근하여 킬을 노리기 좋아요. 점화는 아지르의 체력을 낮추는 데 도움을 줘요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 둔화를 걸며 견제하고 (P)\'암살자의 표식\' 원 경계를 활용해 강화 평타를 노리니 주의하세요. (P)\'혹한의 분노\' 서리 갑옷이 켜져 있으면 (Q)\'오연투척검\' 둔화에 면역이니 서리 갑옷을 유지하며 (W)\'혹한의 서릿발\'로 미니언을 정리하세요.', lv3: '아칼리가 (E)\'표창곡예\'로 표식을 남기고 돌진해 올 때 (E)\'만년 서리\'를 맞춰 기절시키면 딜교환을 이끌어낼 수 있어요. (W)\'황혼의 장막\' 안의 아칼리는 투명해 대상 지정이 안 되지만, (W)\'혹한의 서릿발\'처럼 범위로 휘두르는 스킬은 연막 안에서도 맞으니 아칼리가 있을 만한 곳에 휘두르세요.', lv6: '아칼리가 (R)\'무결처형\'을 사용해 진입할 때 (R)\'빙하 감옥\'을 맞춰 기절시키고 모습을 드러내게 하세요. (R)\'무결처형\' 재사용 돌진은 잃은 체력에 비례해 피해가 커지니 체력을 지키며 정글러의 개입을 유도해요.', item: '심연의 가면을 첫 코어로 선택해 아칼리의 마법 피해에 저항하세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진을 사용하면 아칼리의 순간적인 피해를 줄이고 진입하는 속도를 늦출 수 있어요.' },
    '아크샨': { lv1: '(Q)\'복수의 부메랑\' 견제를 버티며 경험치를 챙기세요. (P)\'혹한의 분노\' 서리 갑옷이 활성화된 상태에서만 짧게 접근해 피해를 줄여야 해요. 무리하게 진입하면 계속 공격받으니 주의하세요.', lv3: '(W)\'혹한의 서릿발\'로 상대를 둔화시켜 거리 조절을 방해하세요. 둔화된 틈을 타 (Q)\'혹한의 맹습\'으로 진입한 뒤 (E)\'만년 서리\'를 사용해 빠르게 기절시켜야 해요. (E)\'영웅의 비상\'으로 도망가기 전에 모든 군중 제어기를 빠르게 연계하는 것이 중요해요.', lv6: '(R)\'빙하 감옥\'을 맞혀 적을 묶은 뒤 아군 정글러와 함께 빠르게 제압하세요. 체력이 낮을 때 (R)\'인과응보\'의 강력한 일격을 맞지 않도록 항상 체력 관리에 신경 써야 해요. 라인을 당겨 (E)\'영웅의 비상\' 이동 경로를 제한하며 정글 개입을 유도하세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 판금 장화로 기본 공격 피해를 줄이고 태양불꽃 방패의 방어력과 체력으로 버티며 라인을 관리하세요.', spell: '점멸과 순간이동을 추천해요. 원거리 견제 때문에 라인 복귀가 잦을 수 있고 빠른 합류로 영향력을 높여야 해요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\' 끝자락에 맞으면 공중으로 띄워지니 항상 거리 조절을 하세요. (P)\'사신 태세\'가 활성화된 기본 공격은 체력을 회복하니 무리하게 평타 교환을 하지 마세요. (W)\'혹한의 서릿발\'을 사용하여 둔화를 걸며 최대한 체력을 보존하세요.', lv3: '(W)\'지옥사슬\'의 범위 안에 갇히면 중앙으로 끌려가 피해를 입으니 표시가 보이면 즉시 벗어나세요. (E)\'파멸의 돌진\'으로 거리를 좁히는 타이밍에 (Q)\'혹한의 맹습\'으로 맞서며 진입하세요. (W)\'혹한의 서릿발\'과 평타로 서리를 쌓은 뒤 (E)\'만년 서리\'로 기절시켜 딜교환을 마무리하세요.', lv6: '(R)\'세계의 종결자\'를 켠 아트록스는 회복량이 매우 높으니 정면 승부는 피하고 거리를 유지하세요. (R)\'빙하 감옥\'으로 상대를 먼저 기절시켜 아군 정글러와 함께 빠르게 제압하세요. 궁극기 지속 시간이 끝난 뒤 (Q)\'혹한의 맹습\'으로 진입해 체력을 깎는 것이 좋아요.', item: '태양불꽃 방패를 가서 체력과 방어력을 높이고 주변에 지속 피해를 주세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (E)\'파멸의 돌진\'과 (R)\'세계의 종결자\'의 강력한 체력 회복을 점화의 치유 감소로 억제하세요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'을 사용해 스킬 뒤에 짧게 돌진하며 강화된 기본 공격을 사용하니 거리를 잘 조절하세요. 1~2레벨에는 암베사가 (Q)\'교활한 휩쓸기\'로 접근할 때 (Q)\'혹한의 맹습\'으로 흐름을 끊으며 대응해요. (P)\'혹한의 분노\'를 유지하여 방어력을 확보하며 버티세요.', lv3: '암베사가 (W)\'배척\'으로 보호막을 얻으며 피해량을 늘리려 하면 무리하게 딜교환을 하지 마세요. (E)\'찢어 가르기\'의 둔화에 걸리지 않도록 주의하며 (W)\'혹한의 서릿발\'로 먼저 둔화를 걸어 대응하세요. (E)\'만년 서리\'를 준비하며 암베사가 들어올 때 (Q)\'혹한의 맹습\'과 함께 기절을 노려보세요.', lv6: '암베사의 (R)\'공개 처형\'은 제압을 걸며 순간 이동하니 체력이 낮을 때는 사거리 밖으로 물러나세요. 제압에 걸리면 정화나 점멸로도 대응할 수 없으니 조심해야 해요. (R)\'빙하 감옥\'을 사용하여 암베사의 진입을 차단하거나 (E)\'만년 서리\'로 기절을 시켜 정글러와 함께 싸우세요.', item: '얼어붙은 심장을 첫 코어로 가서 방어력과 스킬 가속을 얻으세요. 신발은 암베사의 기본 공격 피해를 줄이기 위해 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 암베사가 (R)\'공개 처형\'으로 진입할 때 점멸로 거리를 조절하거나 점화로 마무리 피해를 입히세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 기절을 걸고 (E)\'동상\'으로 피해를 입히며 견제해요. (P)\'혹한의 분노\'를 유지하며 마법 저항력을 얻어 피해를 줄이고, 구체가 터지는 지점을 피해 걸으세요. 무리하게 다가가기보다 체력을 보존하며 다음 기회를 노리세요.', lv3: '(W)\'결정화\' 벽이 세워지면 진입 경로가 막히니 벽이 사라질 때까지 기다리거나 옆으로 돌아가세요. (Q)\'냉기 폭발\'에 맞은 직후에는 (E)\'동상\' 피해가 매우 강력하니 잠시 뒤로 물러나세요. (Q)\'혹한의 맹습\'으로 빠르게 붙은 뒤 (W)\'혹한의 서릿발\'과 (E)\'만년 서리\'를 연계해 상대를 기절시키세요.', lv6: '(R)\'얼음 폭풍\'의 둔화 때문에 접근이 어렵지만 (R)\'빙하 감옥\'을 먼저 맞춰 기절시킨 뒤 빠르게 진입하세요. 애니비아가 치명적인 피해를 입어 (P)\'환생\' 알이 되면 즉시 공격해서 부수어야 해요. (W)\'결정화\' 벽에 막히지 않도록 정글러와 함께 각도를 조절하며 덮치세요.', item: '태양불꽃 방패를 첫 코어로 가서 체력과 방어력을 높이고 근접 전투 피해를 더하세요. 신발은 (Q)\'냉기 폭발\' 기절과 (R)\'얼음 폭풍\' 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'의 기절을 정화로 빠르게 풀고 진입할 수 있어요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'을 두 번 맞춰 회오리로 띄우려 하니 첫 번째 찌르기를 피하며 거리를 유지하세요. (P)\'혹한의 분노\'가 활성화되면 방어력이 올라가니 피해를 입지 않도록 주의하며 미니언을 챙기세요. (W)\'혹한의 서릿발\'로 야스오의 접근을 늦추며 첫 웨이브를 안정적으로 받아내세요.', lv3: '야스오의 (W)\'바람 장막\'은 투사체를 막아내니 (Q)\'혹한의 맹습\'처럼 돌진하는 스킬로 벽을 무시하고 들어가세요. (W)\'혹한의 서릿발\'을 적중시켜 (E)\'만년 서리\' 중첩을 쌓으며 딜교환을 시도하세요. (Q)\'강철 폭풍\'의 회오리가 빠진 타이밍에 진입하면 공중으로 띄워질 위험이 줄어요.', lv6: '(R)\'빙하 감옥\'은 투사체라 (W)\'바람 장막\'에 막히니 장막이 빠진 뒤에 던져 야스오를 기절시키세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 들어올 때 기절을 걸면 빠르게 멈춰 세울 수 있어요. 정글러가 근처에 있다면 (R)\'빙하 감옥\'과 (Q)\'혹한의 맹습\' 연계로 킬을 노려보세요.', item: '강철심장을 첫 코어로 선택하여 체력을 높이며 교전 능력을 키우세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 (P)\'낭인의 길\' 보호막이 깨진 순간 점화로 마무리 피해를 더하면 킬각을 잡기 좋아요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 평타를 사용하며 방어력을 낮추니 초반부터 너무 깊게 붙지 마세요. 1~2레벨에는 (W)\'혹한의 서릿발\'로 서리 중첩을 쌓으며 견제하고 (P)\'혹한의 분노\'를 통해 방어력을 확보하세요. 오공이 (P)\'바위 피부\'로 점점 단단해지기 전에 짧게 교환하고 빠지는 것이 좋아요.', lv3: '오공이 (E)\'근두운 급습\'으로 들어오며 분신을 만들 때 분신에 (E)\'만년 서리\'를 낭비하지 않도록 주의하세요. (W)\'분신 전사\'로 투명해진 오공의 진짜 위치를 확인한 뒤 (W)\'혹한의 서릿발\'로 중첩을 쌓고 (E)\'만년 서리\'를 사용하세요. 오공의 (Q)\'파쇄격\' 사용 여부를 확인하며 대응해야 해요.', lv6: '오공이 (R)\'회전격\'으로 적을 공중에 띄우면 스킬을 사용할 수 없으니 진입 타이밍을 조심하세요. 오공이 (R)\'회전격\'을 쓰기 전에 (R)\'빙하 감옥\'을 맞춰서 진입을 차단하거나 킬각을 노려보세요. 오공의 궁극기가 빠진 후에는 라인을 관리하며 정글러를 부르는 것이 좋아요.', item: '첫 코어로 얼어붙은 심장을 선택해 방어력을 높이고 오공의 공격 속도를 낮추세요. 신발은 오공의 평타 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 오공에게 추가 피해를 입히며 확실하게 마무리하세요.' },
    '오로라': { lv1: '오로라가 (Q)\'이중 저주\'로 계속 견제하며 체력을 깎으려 해요. (P)\'혹한의 분노\'로 얻는 추가 방어력과 마법 저항력을 믿고 끈질기게 버티며 미니언을 챙기세요. 무리하게 다가가기보다 상대의 스킬 쿨타임을 확인하며 거리를 조절하세요.', lv3: '(E)\'마법의 문\'을 사용하면 오로라가 둔화를 걸고 뒤로 물러나니, 이 스킬이 빠진 직후에 (Q)\'혹한의 맹습\'으로 돌진하세요. 빠르게 접근한 뒤 (W)\'혹한의 서릿발\'로 서리 중첩을 쌓고 (E)\'만년 서리\'로 기절시켜 딜교환을 마무리하세요. (W)\'장막 너머로\'로 투명해진 상대는 억지로 쫓지 말고 기다리세요.', lv6: '(R)\'세계의 경계\' 영역 안에서는 오로라가 한쪽에서 건너편으로 점프할 수 있으니 영역 밖에서 기회를 보세요. 오로라가 건너편으로 착지하는 위치를 보고 (R)\'빙하 감옥\'을 맞혀 기절시키면 킬각을 잡을 수 있어요. 영역을 드나들면 내가 둔화되니 (P)\'혹한의 분노\' 서리 갑옷이 켜진 상태에서 진입하고 정글러와 함께 압박하세요.', item: '헤르메스의 발걸음과 끝없는 절망을 추천해요. 헤르메스의 발걸음은 오로라의 마법 피해를 줄이고 둔화 지속시간을 낮춰주며, 끝없는 절망은 방어력과 체력을 높여줘요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 빠르게 라인에 복귀해 주도권을 유지하세요.' },
    '오른': { lv1: '1~2레벨에는 (W)\'혹한의 서릿발\'을 활용해 미니언을 정리하며 오른의 (Q)\'용암 균열\' 기둥이 생기는 위치를 잘 피해 주세요. 오른이 (Q)\'용암 균열\'로 둔화를 걸며 견제할 때 무리하게 붙지 말고 거리를 유지하며 (P)\'혹한의 분노\' 패시브를 활용해 방어력을 챙기세요.', lv3: '(W)\'불꽃 풀무질\'의 마지막 불꽃에 맞아 불안정 상태가 되면 오른의 기본 공격에 뒤로 밀려나니 그동안 오른의 평타 거리 안에 머물지 마세요. (E)\'화염 돌진\'이 지형에 부딪혀 띄우는 것을 조심하며 (Q)\'혹한의 맹습\'으로 진입해 (W)\'혹한의 서릿발\'로 서리 중첩을 쌓으세요. 중첩이 쌓인 뒤 (E)\'만년 서리\'를 사용하여 딜교환을 하세요.', lv6: '오른이 (R)\'대장장이 신의 부름\'을 사용해 정령을 소환하면 정령의 진행 방향과 오른이 돌진할 위치를 주시하세요. (R)\'빙하 감옥\'으로 적을 기절시킨 뒤 (Q)\'혹한의 맹습\'으로 연계하면 킬각을 잡기 좋아요. 오른은 아이템을 업그레이드하며 버티는 힘이 강하므로 라인을 빠르게 밀어 정글러를 호출하세요.', item: '체력을 쌓아 전투를 길게 가져갈 수 있는 강철심장을 첫 코어로 가세요. 신발은 오른의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 (P)\'간이 대장간\'으로 아이템을 만들며 버티기 때문에 순간이동으로 라인 복귀를 빠르게 하는 것이 중요해요.' },
    '올라프': { lv1: '올라프는 (Q)\'역류\'를 던져 방어력을 낮추니 도끼 궤적을 잘 피하며 거리를 조절하세요. (P)\'혹한의 분노\'를 통해 서리 갑옷을 활성화하여 추가 방어력과 마법 저항력을 확보하며 버티는 것이 중요해요. 1~2레벨부터 올라프의 기본 공격이 매우 강력하므로 무리한 교환은 피하세요.', lv3: '올라프가 (W)\'버티기\'를 사용하여 보호막을 얻었을 때는 딜교환을 잠시 멈추고 기다리세요. (W)\'혹한의 서릿발\'로 서리 중첩을 쌓은 뒤 (E)\'만년 서리\'를 적중시켜 짧게 교환하고 빠지세요. 올라프가 (Q)\'역류\'를 맞히고 도끼를 주우러 가는 동안 (Q)\'혹한의 맹습\'으로 진입해 압박하세요.', lv6: '올라프가 (R)\'라그나로크\'를 쓰면 이동 방해 효과에 면역이 되니 (R)\'빙하 감옥\'을 아끼며 기다리세요. 궁극기가 끝난 직후에 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'를 연계해 기절을 노리고 정글러를 호출하세요. 체력이 낮은 올라프는 (P)\'광전사의 분노\'로 인해 회복력이 매우 높으니 마무리까지 주의해야 해요.', item: '판금 장화와 가시 갑옷을 추천해요. 판금 장화로 올라프의 기본 공격 피해를 줄이고 가시 갑옷으로 (P)\'광전사의 분노\'를 통한 회복을 억제하세요.', spell: '점멸과 점화를 추천해요. 올라프는 체력이 낮을수록 (P)\'광전사의 분노\'로 회복이 늘어나니 점화의 치유 감소 효과를 활용하세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'을 여러 차례 맞히면 돌풍으로 띄워 올려요. (Q)\'필멸의 검\' 중첩이 쌓였을 때는 거리를 두어 돌풍을 피하세요. (W)\'혹한의 서릿발\'을 사용해 서리 중첩을 쌓으며 웨이브를 안정적으로 받아내세요.', lv3: '요네가 (E)\'영혼해방\'을 사용하면 영혼이 돌아오는 위치를 파악하며 기다리세요. (W)\'영혼 가르기\'로 보호막을 얻었을 때는 보호막이 사라진 뒤에 (Q)\'혹한의 맹습\'으로 진입하세요. (W)\'혹한의 서릿발\'을 섞어 (E)\'만년 서리\' 스택을 쌓으세요.', lv6: '요네의 (R)\'운명봉인\'에 끌려가 공중에 뜨면 스킬을 쓸 수 없으니 궁극기가 날아오는 일직선에서 비켜서고, 요네가 궁극기를 쓴 직후 (R)\'빙하 감옥\'을 맞혀 반격하세요. (E)\'영혼해방\'이 끝나고 육신이 돌아오는 순간에 (E)\'만년 서리\'를 맞히면 킬을 노리기 좋아요. 요네의 궁극기 사거리가 길기 때문에 라인을 밀 때는 정글러의 위치를 확인하세요.', item: '판금 장화와 얼어붙은 심장을 구매하세요. 판금 장화는 요네의 기본 공격 피해를 줄여주고 얼어붙은 심장은 방어력을 높여줘요.', spell: '점멸과 점화를 추천해요. 요네가 (W)\'영혼 가르기\' 보호막을 사용한 뒤에 점화로 마무리 피해를 더하세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 미니언을 처치하며 무덤을 만들고 체력을 회복해요. 무덤이 많이 쌓이기 전에 (Q)\'혹한의 맹습\'으로 빠르게 접근하여 짧게 교환하세요. (P)\'혹한의 분노\'로 얻는 방어력을 활용하며 요릭의 공격을 받아내세요.', lv3: '요릭이 (E)\'애도의 안개\'를 던져 표식을 남기면 안개 망령이 몰려오니 주의하세요. (W)\'망자의 진\' 벽에 갇혔다면 기본 공격으로 벽을 빠르게 부수고 빠져나오세요. (W)\'혹한의 서릿발\'로 서리를 쌓고 (E)\'만년 서리\'를 사용하여 요릭을 기절시키세요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 마녀와 함께 요릭을 상대하기 어려워요. (R)\'빙하 감옥\'으로 요릭을 묶고 정글러를 호출하여 안개 마녀와 소환물을 함께 정리하세요. 마녀가 소환된 뒤에는 요릭과 너무 깊게 싸우지 말고 라인 관리에 집중하세요.', item: '요릭의 기본 공격 피해를 줄이기 위해 판금 장화를 구매하세요. 첫 코어 아이템은 방어력을 높여주는 얼어붙은 심장이 좋아요.', spell: '점멸과 점화를 추천해요. 요릭의 (Q)\'최후의 의식\' 회복을 점화로 억제하며 킬을 노리세요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세로 평타 피해를 높일 때는 맞딜을 피하며 거리를 유지하세요. (W)\'혹한의 서릿발\'을 활용해 미니언을 밀어내며 라인을 관리하고 적의 접근을 늦추며 준비해요.', lv3: '우디르가 (E)\'불길 쇄도\'를 사용해 돌진하며 기절을 시도하면 (Q)\'혹한의 맹습\'으로 먼저 진입하며 대응하세요. 우디르가 (W)\'강철 갑옷\'으로 보호막과 체력을 회복하는 동안에는 (W)\'혹한의 서릿발\'로 서리 중첩을 쌓으며 기회를 보세요. 우디르가 (E)\'불길 쇄도\'를 재사용하여 이동 불가 면역이 되었다면 (E)\'만년 서리\' 사용을 잠시 미뤄야 해요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 사용해 주변에 둔화를 뿌릴 때는 무리해서 붙지 마세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 면역 상태가 되었을 때는 (R)\'빙하 감옥\'을 아껴두었다가 효과가 끝난 뒤에 꽂으세요. (E)\'만년 서리\'로 기절을 시킨 뒤 (R)\'빙하 감옥\'을 연계하여 적을 확실하게 묶으세요.', item: '판금 장화와 태양불꽃 방패를 선택하세요. 우디르의 기본 공격 피해를 줄이기 위해 판금 장화를 사고, 태양불꽃 방패를 올려 불사르기 피해로 싸움을 도와요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복하는 타이밍에 점화를 사용하여 회복량을 줄이세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'을 던져 둔화를 걸고 (P)\'화염의 메아리\' 평타로 견제해요. 폭약의 낙하지점을 피하며 (W)\'혹한의 서릿발\'로 짧게 딜교환을 하고 빠르게 빠지세요. 1~2레벨에는 무리하게 붙지 말고 (P)\'혹한의 분노\' 서리 갑옷을 유지하며 체력을 관리하세요.', lv3: '우르곳이 (E)\'경멸\'로 돌진하기 전에 (Q)\'혹한의 맹습\'으로 먼저 띄우면 공중에 뜬 동안 (E)\'경멸\'을 쓸 수 없어요. 하지만 (E)\'경멸\'에 먼저 맞으면 뒤로 던져지며 기절하므로 상대의 돌진 경로에서 비켜나세요. (W)\'혹한의 서릿발\'로 서리를 쌓고 (E)\'만년 서리\'로 기절시킨 뒤 짧게 교환하세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞은 뒤 체력이 낮아지면 우르곳이 재사용해 제압하고 처형하니 즉시 거리를 벌리세요. 우르곳이 재사용하기 전에 (R)\'빙하 감옥\'으로 먼저 기절시켜 접근을 막으세요. (Q)\'혹한의 맹습\'과 (E)\'만년 서리\' 연계로 체력을 깎은 뒤 아군 정글러와 함께 덮치세요.', item: '판금 장화를 신어 우르곳의 평타 피해를 줄이세요. 첫 코어로 태양불꽃 방패를 올려 체력과 방어력을 높이고 근접 전투 시 지속 피해를 입히세요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력이 중요하며 (R)\'빙하 감옥\'과 점멸을 연계해 변수를 만들어야 해요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'로 도약하며 체력을 회복하니 1~2레벨에 무리하게 맞붙지 마세요. (W)\'혹한의 서릿발\'로 미니언과 함께 툭툭 쳐서 서리 중첩을 쌓으며 거리를 유지해요. (P)\'혹한의 분노\'가 활성화되어 방어력이 높아진 상태를 활용해 워윅의 공격을 받아내세요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용하면 피해 감소 효과가 있고 끝날 때 공포에 빠뜨리니, 포효가 끝난 뒤에 딜교환을 시작하세요. (W)\'혹한의 서릿발\'로 서리 중첩을 쌓고 (E)\'만년 서리\'로 기절을 시키는 것이 중요해요. 워윅이 (Q)\'야수의 송곳니\'를 길게 눌러 나를 물면 내가 움직일 때 같이 따라오니 도망치기보다 그 자리에서 (W)\'혹한의 서릿발\'로 맞받아치세요.', lv6: '워윅의 (R)\'무한의 구속\'은 제압 효과라 정화로 풀 수 없으니 적 정글러가 근처에 있을 때 특히 주의해야 해요. 먼저 (R)\'빙하 감옥\'을 맞히면 워윅의 돌진을 방해하며 싸움을 주도할 수 있어요. 내 체력이 절반 밑으로 내려가면 (W)\'피의 사냥\'으로 워윅의 이동 속도가 빨라지니 라인을 당겨서 (R)\'무한의 구속\'에 맞지 않도록 조심하세요.', item: '워윅의 기본 공격 피해를 줄이기 위해 판금 장화를 먼저 올려요. 가시 갑옷을 첫 코어로 선택해 워윅의 (P)\'끝없는 허기\'와 (Q)\'야수의 송곳니\' 회복을 억제하세요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'에 의한 회복량을 줄여야 킬을 잡을 수 있어요.' },
    '이렐리아': { lv1: '1~2레벨에는 이렐리아가 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오며 체력을 회복할 수 있으니 미니언과의 거리를 조절하세요. 이렐리아가 미니언을 타고 돌진해 오면 (W)\'혹한의 서릿발\'로 둔화를 걸어 추가 진입을 늦추세요. 이렐리아가 (P)\'아이오니아의 열정\' 중첩을 쌓기 전에 평타로 응수하며 (P)\'혹한의 분노\'를 활용하세요.', lv3: '이렐리아가 (W)\'저항의 춤\'을 사용하여 물리 피해를 줄이는 동안에는 억지로 교환하지 마세요. (E)\'쌍검협무\'가 날아오는 길목을 피해 스턴을 방지하고, (Q)\'혹한의 맹습\'으로 이렐리아의 진입을 끊어주어야 해요. 이렐리아가 (Q)\'칼날 쇄도\'로 들어올 때 (E)\'만년 서리\'를 사용하여 기절을 시키면 교환을 시작할 수 있어요.', lv6: '이렐리아가 (R)\'선봉진격검\'을 사용해 결계를 만들면 결계 안에서 피해를 입고 둔화되니 주의하세요. 이렐리아의 궁극기가 빠진 뒤 (R)\'빙하 감옥\'을 활용해 기절시키고 (Q)\'혹한의 맹습\'으로 연계하면 킬을 노릴 수 있어요. 이렐리아가 불안정 상태의 대상에게 (Q)\'칼날 쇄도\'를 연달아 쓰지 못하도록 라인을 관리하며 정글러를 호출하세요.', item: '이렐리아의 기본 공격 피해를 줄이기 위해 판금 장화를 선택하세요. 첫 코어 아이템으로는 체력을 높여주는 강철심장을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 이렐리아의 (Q)\'칼날 쇄도\'를 통한 체력 회복 효과를 줄이세요.' },
    '일라오이': { lv1: '(P)\'고대신의 예언자\' 촉수가 있는 벽 근처에서는 싸우지 마세요. 일라오이가 (Q)\'촉수 강타\'를 사용할 때 정면 범위를 피해 거리 조절을 하세요. (W)\'혹한의 서릿발\'을 사용해 적을 둔화시키며 경험치만 챙기는 식으로 조심스럽게 받아내세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 일라오이가 내 영혼을 때려 피해를 입히니, 빠르게 일라오이로부터 거리를 벌리세요. 다만 영혼에서 너무 멀어지면 내가 숙주가 되어 촉수가 생기니 적당한 거리에서 대치하세요. (Q)\'혹한의 맹습\'으로 진입해 (W)\'혹한의 서릿발\'로 서리를 쌓고 (E)\'만년 서리\'로 기절시켜 짧게 딜교환을 하고 빠지세요.', lv6: '(R)\'믿음의 도약\'을 쓰면 주변에 촉수가 많이 소환되니, 성상을 내리치는 순간 즉시 범위 밖으로 벗어나세요. 일라오이가 궁극기를 사용한 뒤 촉수가 사라질 때까지 기다렸다가 (R)\'빙하 감옥\'으로 기절시켜 정글러와 함께 잡아내세요. 촉수가 없는 평지에서 싸우는 구도를 만들어 피해를 최소화하세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 판금 장화로 일라오이의 기본 공격 피해를 줄이고 태양불꽃 방패의 방어력과 체력으로 버티며 싸우세요.', spell: '점멸과 순간이동을 추천해요. 일라오이가 라인을 밀어내므로 순간이동으로 빠르게 복귀해 손실을 줄이세요.' },
    '자크': { lv1: '자크가 (Q)\'탄성 주먹\'으로 멀리서 견제하며 (P)\'세포 분열\' 조각을 만들지 못하게 거리를 조절하세요. 1~2레벨에는 (W)\'혹한의 서릿발\'을 활용해 미니언을 밀어내며 자크가 다가오기 전에 압박하세요. 자크가 조각을 주우러 이동할 때를 노려 (Q)\'혹한의 맹습\'으로 거리를 좁히며 딜교환을 시도하세요.', lv3: '자크가 (E)\'새총 발사\'로 날아올 때 (Q)\'혹한의 맹습\'으로 맞받아쳐 공중으로 띄우며 대응하세요. 자크가 (W)\'불안정 물질\'로 주변에 피해를 주려 하면 (W)\'혹한의 서릿발\'로 둔화를 걸어 거리를 유지하세요. (E)\'만년 서리\' 중첩을 빠르게 쌓아 자크가 (P)\'세포 분열\' 조각을 흡수하기 전에 기절을 시키는 것이 중요해요.', lv6: '자크가 (R)\'바운스!\'로 튀어 오르며 다가올 때 (R)\'빙하 감옥\'을 맞춰 기절시키고 군중 제어 연계를 이어가세요. 자크가 체력이 낮아져 (P)\'세포 분열\'로 갈라지면 살아남은 조각의 체력에 비례해 부활하니 조각을 공격해 체력을 줄이세요. 자크가 조각을 흡수해 체력을 회복하지 못하도록 정글러를 호출해 함께 압박하세요.', item: '자크의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템으로는 지속적인 전투와 방어력을 위해 태양불꽃 방패를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 자크가 (P)\'세포 분열\' 조각을 통해 체력을 회복하는 것을 억제하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 1~2레벨에는 무리하게 맞붙지 마세요. (W)\'혹한의 서릿발\'로 미니언을 밀어내며 거리를 유지하고 자헨의 (P)\'전쟁 단련\' 중첩이 쌓이지 않게 주의해요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 끌어당기려 하면 (Q)\'혹한의 맹습\'으로 먼저 진입하여 자헨의 움직임을 끊으세요. 자헨의 (E)\'찬란한 쇄도\'가 닿지 않는 위치에서 (W)\'혹한의 서릿발\'로 둔화를 묻히고 스택을 쌓는 것이 중요해요.', lv6: '자헨이 (R)\'단호한 판결\'로 높이 뛰어오르면 착지 지점을 피해 자헨의 회복을 방해하세요. 자헨은 (P)\'전쟁 단련\'의 결심이 가득 차면 부활할 수 있으니, (R)\'빙하 감옥\'과 (E)\'만년 서리\'로 묶어 킬을 낸 뒤에도 바로 방심하지 말고 부활에 대비하세요.', item: '강철심장을 첫 코어로 올려 체력을 확보하세요. 신발은 자헨의 평타 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 자헨의 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'을 통한 체력 회복을 줄이세요.' },
    '잭스': { lv1: '잭스는 (Q)\'도약 공격\'으로 순식간에 접근하며 (W)\'무기 강화\'를 활용해 강력한 피해를 입힐 수 있어요. 1~2레벨에는 (W)\'혹한의 서릿발\'로 잭스의 접근을 늦추며 거리를 조절하세요. 첫 웨이브를 받아내며 (Q)\'혹한의 맹습\'으로 잭스의 진입에 대응하며 버텨내세요.', lv3: '잭스가 (E)\'반격\'을 사용하면 세주아니의 기본 공격을 모두 피하니 주의하세요. (E)\'반격\'은 기본 공격만 피하고 광역 스킬 피해는 줄일 뿐이니 그동안 (W)\'혹한의 서릿발\'로 서리 중첩을 쌓아두세요. (E)\'반격\'이 끝나 기절을 피한 직후 (Q)\'혹한의 맹습\'으로 진입하며 딜교환을 하세요.', lv6: '잭스가 (R)\'무기의 달인\'을 켜면 방어력과 마법 저항력이 올라가니 정면 싸움은 조심하세요. (R)\'빙하 감옥\'으로 잭스를 묶은 뒤 (E)\'만년 서리\'로 기절을 연계해 킬각을 보세요. 정글러를 불러 잭스가 (Q)\'도약 공격\'으로 도망가지 못하게 압박하는 것이 좋아요.', item: '잭스의 공격 속도를 억제하기 위해 얼어붙은 심장을 첫 코어로 선택해요. 신발은 잭스의 물리 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 잭스를 처치하기 쉽게 만드세요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 계속 쏘며 견제하니 (P)\'혹한의 분노\'의 추가 방어력과 마법 저항력을 활용해 피해를 줄이세요. 무리하게 다가가기보다 미니언 뒤에서 체력을 보존하며 첫 웨이브를 받아내세요. 제이스가 해머로 (Q)\'하늘로!\'를 쓰며 진입할 때 거리를 조절하며 피해를 최소화하세요.', lv3: '제이스의 (E)\'천둥 강타\'에 밀려나면 딜교환이 어렵기에 해당 스킬이 빠진 뒤에 (Q)\'혹한의 맹습\'으로 진입하세요. 진입 후 (W)\'혹한의 서릿발\'로 서리 중첩을 빠르게 쌓고 (E)\'만년 서리\'로 기절시켜 흐름을 끊으세요. 캐논 형태의 (E)\'가속 관문\'을 통해 날아오는 (Q)\'전격 폭발\'은 옆으로 움직여 피하세요.', lv6: '(R)\'빙하 감옥\'을 맞히면 원거리에서도 강제로 전투를 시작할 수 있으니 제이스의 이동 경로를 예측해 던지세요. (R)\'머큐리 캐논\'으로 변환한 직후의 첫 공격은 방어력을 깎으니 이때는 (P)\'혹한의 분노\'가 켜져 있는지 확인하세요. 정글러가 왔을 때 (R)\'빙하 감옥\'으로 묶어두면 제이스가 (E)\'천둥 강타\'로 도망가기 전에 처치할 수 있어요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 판금 장화로 제이스의 기본 공격 피해를 줄이고 태양불꽃 방패의 체력과 방어력으로 견제를 견디며 주변에 피해를 입히세요.', spell: '점멸과 순간이동을 추천해요. (R)\'빙하 감옥\'과 점멸을 연계해 변수를 만들고 순간이동으로 라인 복귀와 합류를 빠르게 하세요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 지정한 지역의 적을 공중으로 띄우고 둔화를 주니 지면이 파열되는 표시를 보고 빠르게 피하세요. (E)\'날카로운 가시\'는 둔화만 걸 뿐 (Q)\'혹한의 맹습\' 돌진을 막지 못하니 맞은 뒤에도 돌진으로 거리를 좁힐 수 있어요. (W)\'혹한의 서릿발\'을 사용해 미니언을 밀어내며 초가스가 (P)\'육식\'으로 체력을 회복하지 못하도록 압박하세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 쓰면 침묵 때문에 스킬을 쓸 수 없으니 원뿔 범위 밖으로 움직이세요. 침묵을 피한 뒤 (Q)\'혹한의 맹습\'으로 진입하고 (W)\'혹한의 서릿발\'을 맞혀서 (E)\'만년 서리\' 스택을 쌓아야 해요. 초가스가 (Q)\'파열\'을 사용하기 전에 먼저 들어가서 싸움을 유도하세요.', lv6: '초가스의 (R)\'포식\'은 방어력을 무시하는 고정 피해를 주니 체력이 낮을 때는 거리를 유지하세요. (R)\'빙하 감옥\'을 맞춰 기절시킨 뒤 (E)\'만년 서리\'를 연계하면 초가스가 (R)\'포식\'을 쓰기 전에 끝낼 수 있어요. 정글러와 함께 압박해 초가스가 성장하지 못하게 하세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 가세요. 초가스의 마법 피해와 군중 제어 지속 시간을 줄이기 위해 헤르메스의 발걸음을 사고, 지속적인 전투를 위해 태양불꽃 방패를 선택해요.', spell: '점멸과 점화. 초가스가 (P)\'육식\'으로 체력을 회복하는 것을 억제하며 킬을 노리기 좋아요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\'로 보호막을 얻고 (Q)\'정확성 프로토콜\'의 강화 공격을 넣으면 매우 강한 구간이에요. 1~2레벨에는 (W)\'혹한의 서릿발\'로 미니언과 함께 견제하며 서리 중첩을 쌓는 데 집중하세요. 카밀의 보호막이 활성화된 동안에는 무리하게 (Q)\'혹한의 맹습\'으로 진입하지 마세요.', lv3: '카밀의 (W)\'전술적 휩쓸기\'는 바깥쪽 절반에 맞으면 둔화와 추가 피해를 입고 카밀의 체력을 회복시키니 원뿔의 바깥쪽을 피하세요. 카밀이 (E)\'갈고리 발사\'로 진입하며 기절을 노릴 때 (Q)\'혹한의 맹습\'을 사용하여 먼저 띄우거나 거리를 조절하세요. 카밀의 (W)\'전술적 휩쓸기\'를 먼저 빼낸 뒤에 (E)\'만년 서리\'로 기절을 연결하는 것이 좋아요.', lv6: '카밀의 (R)\'마법공학 최후통첩\'에 갇히면 일정 지역 내에서 탈출할 수 없으니 주의해야 해요. 카밀이 궁극기를 쓰기 전에 (R)\'빙하 감옥\'을 먼저 맞춰서 카밀의 진입을 차단하거나 아군 정글러를 부르세요. 카밀의 (E)\'갈고리 발사\'가 빠진 타이밍에 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'를 연계하여 정글러와 함께 교전을 유도하세요.', item: '강철심장을 첫 코어로 가서 체력을 높이고 전투를 길게 이어가세요. 신발은 카밀의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '카사딘': { lv1: '1~2레벨에는 카사딘의 (Q)\'무의 구체\' 보호막이 생성되는 것을 확인하며 무리하게 진입하지 마세요. (P)\'혹한의 분노\' 패시브를 유지하며 안정적으로 미니언을 받아먹으며 버텨요.', lv3: '3레벨 이후에는 카사딘의 (Q)\'무의 구체\' 보호막이 빠진 타이밍에 (Q)\'혹한의 맹습\'으로 진입하세요. (W)\'혹한의 서릿발\'로 서리를 쌓고 (E)\'만년 서리\'를 사용해 카사딘의 움직임을 멈춰요.', lv6: '6레벨 이후에는 카사딘이 (R)\'균열 이동\'으로 순간이동해 빠져나가니, 순간이동한 직후 위치를 보고 (R)\'빙하 감옥\'을 맞혀 기절시키세요. 카사딘의 주요 스킬이 빠진 것을 확인하고 정글러와 함께 교전을 유도해요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 가요. 카사딘의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 사고 태양불꽃 방패로 지속적인 전투력을 높여요.', spell: '점멸과 점화. (R)\'빙하 감옥\'을 맞춘 뒤 점화로 피해를 입히며 카사딘을 마무리해요.' },
    '카시오페아': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\' 견제를 최대한 버티며 (P)\'혹한의 분노\' 서리 갑옷을 유지하세요. 무리하게 진입하기보다 경험치만 챙기며 거리 조절을 하는 것이 좋아요.', lv3: '(W)\'독기의 늪\'이 깔려 있으면 (Q)\'혹한의 맹습\'을 사용할 수 없으니 상대의 스킬 사용을 확인하고 진입하세요. (W)\'혹한의 서릿발\'로 서리를 쌓은 뒤 (E)\'만년 서리\'로 빠르게 기절시켜 딜교환을 마쳐야 해요.', lv6: '(R)\'빙하 감옥\'을 맞힌 뒤 빠르게 진입하되 (R)\'석화의 응시\'에 정면으로 노출되지 않도록 주의하세요. 라인을 당겨 정글러를 부르면 (R)\'빙하 감옥\'의 광역 둔화 덕분에 킬을 잡기 편해요.', item: '헤르메스의 발걸음과 대자연의 힘을 추천해요. 마법 저항력을 높이고 강인함으로 군중 제어 지속시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. (E)\'쌍독니\'의 체력 회복을 억제하고 확실한 킬각을 잡기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 날려 (P)\'폭풍의 표식\'을 남기니 표창이 날아오는 타이밍에 미니언 뒤로 숨으세요. (W)\'혹한의 서릿발\'로 미니언을 밀어내며 라인을 관리하고, 케넨의 표식이 쌓이지 않게 거리를 조절하며 받아내세요.', lv3: '케넨이 (E)\'번개 질주\'로 들어오며 표식을 남기려 하면 (Q)\'혹한의 맹습\'으로 먼저 진입해 공중으로 띄우세요. 케넨이 (Q)\'천둥의 표창\'을 허공에 날리도록 유도한 뒤 (W)\'혹한의 서릿발\'로 둔화를 걸고 딜교환을 시도하세요. 케넨의 표식이 쌓여 기절하기 전에 (Q)\'혹한의 맹습\'을 맞춰 흐름을 끊는 것이 중요해요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 주변에 큰 피해를 주니 그 범위 안에 오래 머물지 마세요. (R)\'빙하 감옥\'을 맞히면 케넨의 스킬 연계를 끊고 킬각을 잡을 수 있어요. 케넨의 궁극기가 빠진 직후에 정글러와 함께 압박하면 훨씬 수월하게 앞서갈 수 있어요.', item: '첫 코어로 심연의 가면을 가서 케넨의 마법 피해를 견디고 스킬 가속을 확보하세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 신으면 좋아요.', spell: '점멸과 탈진을 추천해요. 케넨이 (E)\'번개 질주\'로 들어오며 폭딜을 넣을 때 탈진을 사용하면 피해량을 낮출 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 오르기 전까지 공격 사거리가 짧은 구간이니 이때 압박하세요. (W)\'혹한의 서릿발\'로 미니언을 밀어넣으며 케일이 미니언을 챙기기 어렵게 만드세요. 케일의 (Q)\'광휘의 일격\'에 맞으면 방어력이 줄어드니 주의하며 거리를 유지해요.', lv3: '(Q)\'혹한의 맹습\'으로 진입하여 케일을 띄운 뒤 (W)\'혹한의 서릿발\'을 사용하여 서리 중첩을 쌓으세요. 케일이 (W)\'천상의 축복\'으로 체력을 회복하며 도망가려 하면 (W)\'혹한의 서릿발\'로 둔화를 걸어 따라가야 해요.', lv6: '케일이 (R)\'신성한 심판\'으로 무적 상태가 되면 그동안 피해가 들어가지 않으니 궁극기 사용 여부를 꼭 확인하세요. 케일의 (R)\'신성한 심판\'이 빠진 직후 (R)\'빙하 감옥\'을 사용하여 기절을 걸고 딜교환을 시작하세요.', item: '헤르메스의 발걸음과 태양불꽃 방패를 가세요. 케일의 마법 피해를 줄이고 불사르기 피해를 입혀요.', spell: '점멸과 점화. 초반에 점화로 케일의 체력을 깎아 성장을 늦추세요.' },
    '코그모': { lv1: '(Q)\'부식성 침\'의 긴 사거리 때문에 초반에는 거리를 조절하며 미니언을 받아먹어야 해요. (W)\'혹한의 서릿발\'로 짧게 딜교환하며 (P)\'혹한의 분노\'가 발동될 수 있도록 관리하세요.', lv3: '(Q)\'혹한의 맹습\'을 사용하여 코그모에게 돌진하며 진입을 시도하세요. (E)\'공허의 분비물\'이 남긴 흔적을 피해 움직이며 (W)\'혹한의 서릿발\'로 둔화를 쌓아야 해요.', lv6: '(R)\'빙하 감옥\'을 적중시킨 뒤 (E)\'만년 서리\'로 이어지는 스킬 연계를 통해 킬을 노려보세요. 코그모가 (R)\'살아있는 곡사포\'로 멀리서 공격할 수 있으니 정글러를 불러 함께 압박하세요.', item: '헤르메스의 발걸음과 가시 갑옷을 추천해요. 코그모의 마법 피해를 견디고 기본 공격에 대응하기 위해서예요.', spell: '점멸과 점화. (Q)\'혹한의 맹습\'과 함께 사용하여 코그모를 빠르게 제압해야 해요.' },
    '코르키': { lv1: '(Q)\'인광탄\' 견제에 체력이 너무 빠지지 않게 주의하며 미니언 근처에서 무빙해요. (Q)\'혹한의 맹습\'을 아껴두었다가 코르키가 무리하게 다가올 때 사용하며 버텨요. (P)\'혹한의 분노\'를 유지하며 최대한 안정적으로 라인을 받아먹어야 해요.', lv3: '코르키가 (E)\'개틀링 건\'을 사용하여 방어력을 낮추기 전에 (Q)\'혹한의 맹습\'으로 진입해요. (W)\'혹한의 서릿발\'로 둔화를 걸고 (E)\'만년 서리\'를 맞히는 연계를 시도하세요. 코르키의 (W)\'발키리\' 이동 경로를 예측해 스킬을 맞히는 것이 중요해요.', lv6: '(R)\'빙하 감옥\'으로 코르키를 기절시키면 아군 정글러를 불러서 킬을 노려보세요. 코르키가 (R)\'미사일 폭격\'을 쌓기 전에 먼저 스킬을 쏟아부어야 해요. 라인을 당겨두고 코르키의 (R)\'미사일 폭격\' 범위를 경계하며 싸워야 해요.', item: '마법 피해를 줄이기 위해 헤르메스의 발걸음을 먼저 올려요. 체력과 방어력을 보충하며 버티기 위해 태양불꽃 방패를 첫 코어로 선택해요.', spell: '점멸과 점화. 코르키의 도주를 막고 킬을 확실히 마무리하기 위해 점화가 좋아요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 활용한 평타와 (Q)\'실명 공격\'으로 멀리서 견제하며 압박하는 구간이 있어요. (Q)\'혹한의 맹습\'은 퀸이 스킬을 뺀 뒤 사용하려고 아껴 두고, (P)\'혹한의 분노\'의 서리 갑옷이 유지되도록 피해를 관리하세요. 1~2레벨에는 무리한 진입보다는 미니언을 챙기며 버티는 것이 좋아요.', lv3: '퀸이 (E)\'공중제비\'로 들어왔다가 뒤로 물러날 때 (Q)\'혹한의 맹습\'으로 추격하며 딜교환을 하세요. 퀸의 (E)\'공중제비\'가 빠진 타이밍을 노려 (W)\'혹한의 서릿발\'로 서리 중첩을 쌓는 것이 중요해요. (Q)\'실명 공격\'에 맞아 시야가 좁아지면 퀸의 위치를 놓치지 않도록 주의하세요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 다른 라인에 개입하면 미니언을 관리하며 정글러를 부르세요. 퀸이 근처에 있다면 (R)\'빙하 감옥\'을 맞춰서 이동을 제약하고 (E)\'만년 서리\'로 이어가세요. (R)\'빙하 감옥\'을 맞춘 뒤에는 확실하게 CC를 연계해야 킬을 낼 수 있어요.', item: '판금 장화와 강철심장을 추천해요. 판금 장화는 퀸의 기본 공격 피해를 줄여주고 강철심장은 체력을 높이며 전투 지속력을 올려줘요.', spell: '점멸과 탈진을 추천해요. 퀸이 (E)\'공중제비\'나 (R)\'후방 지원\'으로 들어와서 피해를 입힐 때 탈진을 사용하여 피해량을 줄이세요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸고 두 번 적중하면 충격파로 끌어당겨요. (W)\'혹한의 서릿발\'로 먼저 견제하며 거리 조절을 하고, (Q)\'엔토포 타격\'의 두 번째 중첩이 쌓이지 않도록 짧게 딜교환하고 빠지세요. 첫 웨이브에서는 (P)\'혹한의 분노\'의 서리 갑옷을 유지하며 체력 손실을 최소화하세요.', lv3: '크산테가 (E)\'발놀림\'으로 진입하면 (W)\'혹한의 서릿발\'과 평타로 빠르게 중첩을 쌓아 (E)\'만년 서리\'로 기절시키세요. (W)\'길을 여는 자\'는 저지 불가 돌진으로 적을 밀어내고 기절시키니, 충전 동작이 보이면 (Q)\'혹한의 맹습\'을 쓰지 말고 옆으로 피하세요. (W)\'길을 여는 자\'가 빠진 직후가 가장 안전하게 딜교환을 할 수 있는 타이밍이에요.', lv6: '(R)\'총공세\'를 사용한 크산테는 방어력이 감소하지만 공격 속도와 피해량이 올라가니 정면 승부는 피하세요. 크산테가 (R)\'총공세\'로 밀어내려 할 때 (R)\'빙하 감옥\'으로 먼저 기절시켜 흐름을 끊으세요. 라인을 밀어 넣은 뒤 정글러를 불러 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'로 갱킹에 호응하세요.', item: '끝없는 절망을 첫 코어로 선택해 챔피언 전투 시 체력을 회복하며 버티세요. 신발은 크산테의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 순간이동을 통해 라인 복귀 시간을 줄이고 운영에 집중하세요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 붙잡아 끌어당기며 초반에 매우 공격적으로 나와요. (Q)\'덫날리기\'에 걸렸다면 최대한 클레드에게서 멀리 떨어져 추가 피해를 피하고, (W)\'혹한의 서릿발\'로 적을 둔화시키며 거리를 유지하세요. 첫 웨이브에서는 무리하게 싸우기보다 (W)\'혹한의 서릿발\'로 미니언과 함께 밀어내며 체력을 보존하세요.', lv3: '(E)\'이랴!\'로 돌진해 들어오는 클레드를 (Q)\'혹한의 맹습\'으로 끊어주거나 공중으로 띄워 흐름을 끊으세요. (W)\'버럭버럭\'이 켜져 평타 속도가 빨라진 상태에서는 (E)\'만년 서리\'로 기절시키기 전까지 정면 대결을 피하세요. (W)\'혹한의 서릿발\'과 평타로 서리 중첩을 빠르게 쌓은 뒤 (E)\'만년 서리\'로 기절시켜 짧게 딜교환하고 빠지세요.', lv6: '(R)\'돌겨어어억!!!\'으로 돌진하는 클레드는 보호막을 두르고 들어오니 돌진 경로에서 벗어나 보호막이 빠지기를 기다리세요. 클레드가 스칼에서 내려 원거리 공격으로 용기를 채우려 할 때 (R)\'빙하 감옥\'으로 기절시키고 진입해 처치하세요. 정글러가 왔을 때 (Q)\'혹한의 맹습\'으로 진입해 강력한 군중 제어 연계를 이어가세요.', item: '얼어붙은 심장을 가서 방어력을 높이고 상대의 공격 속도를 낮춰 (W)\'버럭버럭\'의 효율을 떨어뜨리세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력과 운영이 중요하며 (R)\'빙하 감옥\'과 점멸을 연계해 변수를 만들기 좋아요.' },
    '탐켄치': { lv1: '탐 켄치가 (Q)\'혀 채찍\'으로 (P)\'절대 미각\' 중첩을 쌓으며 견제하니 미니언을 사이에 두고 거리를 조절하세요. 중첩이 모두 쌓여 기절하지 않도록 주의하며 (W)\'혹한의 서릿발\'로 짧게 딜교환을 시도해요. 1~2레벨 구간에는 무리하게 들어가기보다 서리 갑옷을 유지하며 버티는 것이 좋아요.', lv3: '탐 켄치의 (W)\'심연 잠수\'가 사용된 것을 확인한 뒤 (Q)\'혹한의 맹습\'으로 진입하세요. 탐 켄치가 (E)\'두꺼운 피부\'를 사용해 보호막을 생성하면 피해를 아끼며 보호막이 사라질 때까지 기다려요. (W)\'혹한의 서릿발\'로 서리를 쌓고 (E)\'만년 서리\'를 맞히는 구도를 만드세요.', lv6: '탐 켄치의 (R)\'집어삼키기\' 중첩이 쌓이지 않도록 평타 교환을 조심하세요. (R)\'빙하 감옥\'을 적중시켜 기절시킨 뒤 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'로 연계하여 공격하세요. 정글러를 호출하여 탐 켄치가 (W)\'심연 잠수\'로 도망치지 못하게 압박하는 것이 좋아요.', item: '강철심장을 첫 코어로 선택하여 체력을 빠르게 쌓으세요. 신발은 탐 켄치의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 체력 회복 효과를 줄이며 압박하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치고 둔화를 걸며 강하게 압박해요. (P)\'혹한의 분노\'를 활용해 방어력을 높이며 버티고, 평타 교환을 짧게 가져가며 (Q)\'혹한의 맹습\' 진입 각을 보세요.', lv3: '트런들이 (E)\'얼음 기둥\'으로 거리를 벌리려 하니 주의하세요. 트런들의 (Q)\'깨물기\'가 빠진 뒤에 (Q)\'혹한의 맹습\'으로 진입하고 (W)\'혹한의 서릿발\'로 서리를 쌓으세요. (E)\'만년 서리\'를 사용해 기절을 시키면 딜교환을 이끌 수 있어요.', lv6: '트런들이 (R)\'진압\'을 사용하면 체력과 방어력을 빼앗기니 즉시 거리를 벌리세요. (R)\'빙하 감옥\'으로 트런들을 기절시킨 뒤 아군 정글러와 합류하여 싸우세요. 트런들은 근처 유닛이 죽을 때 (P)\'헌납\'으로 회복하니 미니언이 많은 곳에서는 조심하세요.', item: '판금 장화와 얼어붙은 심장을 추천해요. 트런들의 기본 공격 피해를 줄이고 주변 적의 공격 속도를 낮출 수 있어요.', spell: '점멸과 점화를 추천해요. 트런들은 (P)\'헌납\'으로 체력을 회복하고 (W)\'얼음 왕국\' 안에서 회복량이 늘어나니 점화로 회복량을 줄이세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 모아 치명타 확률을 높이고 (Q)\'피의 갈망\'으로 체력을 회복하며 강하게 압박해요. 초반에는 무리하게 붙기보다 (W)\'혹한의 서릿발\'로 거리를 조절하며 미니언을 챙기세요. 트린다미어의 평타 공격을 최대한 피하며 (P)\'혹한의 분노\' 효과를 유지하는 것이 중요해요.', lv3: '(Q)\'혹한의 맹습\'으로 진입한 뒤 (W)\'혹한의 서릿발\'을 사용하여 (E)\'만년 서리\' 중첩을 쌓으세요. 트린다미어가 (W)\'조롱의 외침\'을 써서 도망가는 세주아니를 둔화시키려 하면 정면에서 맞서며 (E)\'만년 서리\'를 준비하세요. 트린다미어의 (E)\'회전 베기\'가 빠진 타이밍에 짧은 딜교환을 시도하는 것이 좋아요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 사용하면 죽지 않으므로 모든 스킬을 쏟아붓지 말고 지속시간이 끝날 때까지 기다리세요. (R)\'불사의 분노\'가 종료된 직후 (R)\'빙하 감옥\'과 (E)\'만년 서리\'를 연계하면 킬을 노릴 수 있어요. 정글러가 근처에 있다면 (Q)\'혹한의 맹습\'으로 빠르게 진입하여 함께 싸우세요.', item: '첫 코어로 가시 갑옷을 가서 기본 공격에 맞을 때 발생하는 효과를 노리세요. 신발은 기본 공격으로 받는 피해량을 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과를 통해 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하는 것을 억제하세요.' },
    '티모': { lv1: '티모의 (Q)\'실명 다트\'와 (E)\'맹독 다트\' 때문에 초반에 체력을 관리하기가 매우 어려워요. (W)\'혹한의 서릿발\'을 활용해 미니언을 정리하며 체력을 보존하고 티모의 공격 사거리 밖에서 움직임을 조절하세요. 수풀 속에서 (P)\'유격 전투\'로 갑자기 나타날 수 있으니 주의하며 라인을 당겨서 받아내세요.', lv3: '티모의 (Q)\'실명 다트\'를 맞으면 평타를 통한 (E)\'만년 서리\' 스택 쌓기가 힘들어지니 주의하세요. 티모가 (Q)\'실명 다트\'를 헛되이 사용하도록 유도한 뒤 (Q)\'혹한의 맹습\'으로 빠르게 접근하세요. 접근 후에는 (W)\'혹한의 서릿발\'로 둔화를 걸고 스택을 쌓아 티모를 기절시켜야 해요.', lv6: '(R)\'빙하 감옥\'을 적중시키면 티모를 확실하게 묶을 수 있으니 거리를 잘 재세요. 티모가 깔아둔 (R)\'유독성 함정\'을 밟으면 이동 속도가 느려지니 버섯을 피해 다니는 것이 중요해요. 티모가 (W)\'신속한 이동\'으로 도망치려 해도 (R)\'빙하 감옥\'의 범위로 묶어버리면 킬을 노릴 수 있어요.', item: '헤르메스의 발걸음을 가서 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템으로는 마법 저항력을 높여주는 심연의 가면을 추천해요.', spell: '점멸과 점화를 추천해요. 티모의 체력이 낮아졌을 때 (R)\'빙하 감옥\'과 함께 사용하면 확실하게 잡아낼 수 있어요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 던져서 멀리서 견제하며 1~2레벨 구간에서 강한 모습을 보여요. (P)\'필멸자의 의지\'가 쌓여 강화된 창을 맞지 않도록 거리를 조절하며 미니언을 챙기세요. (W)\'혹한의 서릿발\'로 파밍을 도와주며 상대의 접근을 경계하세요.', lv3: '판테온의 (W)\'방호의 도약\'을 먼저 빼는 것이 좋아요. 판테온이 (E)\'방패 돌격\'을 사용하면 정면에서 공격해도 피해를 입히기 어려우니 옆이나 뒤를 노리세요. (E)\'만년 서리\' 중첩을 쌓아 판테온의 움직임을 제약하며 딜교환을 하세요.', lv6: '판테온이 (R)\'거대 유성\'을 사용해 날아오면 착지 지점을 확인하고 (R)\'빙하 감옥\'을 맞춰서 움직임을 봉쇄하세요. 판테온이 궁극기로 다른 라인에 개입하면 정글러와 함께 대응하며 라인을 관리하세요. (E)\'만년 서리\'와 (R)\'빙하 감옥\'의 연계를 통해 판테온을 묶어두면 킬을 만들어낼 수 있어요.', item: '판금 장화와 강철심장을 추천해요. 판금 장화는 판테온의 기본 공격 피해를 줄여주고 강철심장은 체력을 높여 전투를 길게 가져가게 도와줘요.', spell: '점멸과 탈진을 추천해요. (W)\'방호의 도약\'으로 들어오는 판테온의 피해량을 감소시켜 생존력을 높일 수 있어요.' },
    '피들스틱': { lv1: '1~2레벨에는 (E)\'수확\'의 둔화와 침묵을 조심하며 체력 관리에 집중하세요. (P)\'혹한의 분노\'가 유지되는 동안에는 상대의 둔화 효과를 무시할 수 있으니 이를 활용해 거리를 좁히세요. 무리하게 진입하다 (Q)\'공포\'에 걸리면 체력을 많이 잃으니 주의해요.', lv3: '(Q)\'혹한의 맹습\'으로 빠르게 접근한 뒤 (W)\'혹한의 서릿발\'을 사용해 서리 중첩을 빠르게 쌓으세요. 상대가 (W)\'풍작\'으로 체력을 회복하려고 정신을 집중할 때 (E)\'만년 서리\'로 기절시켜 흐름을 끊는 것이 중요해요. (E)\'수확\'의 침묵 범위 중심에 들어가지 않도록 주의하며 딜교환하세요.', lv6: '상대가 시야 밖에서 (R)\'까마귀 폭풍\'으로 진입할 때 (R)\'빙하 감옥\'을 던져 즉시 멈추게 하세요. 정글러가 근처에 있다면 (Q)\'혹한의 맹습\'과 (E)\'만년 서리\'로 피들스틱을 묶어 확실하게 킬각을 잡으세요. 라인을 밀어넣고 수풀에 와드를 설치해 상대의 기습 경로를 미리 차단하는 것이 좋아요.', item: '헤르메스의 발걸음과 끝없는 절망을 추천해요. 강인함으로 공포 지속시간을 줄이고 전투 중 체력을 회복하며 버티기 좋아요.', spell: '점멸과 순간이동을 추천해요. (R)\'빙하 감옥\'의 적중률을 높이고 라인 복귀를 빠르게 하기 위해서예요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 돌진하며 딜교환을 시도하니 거리 조절에 신경 쓰세요. 1~2레벨에는 (W)\'혹한의 서릿발\'을 활용해 피오라를 둔화시키며 서리 중첩을 쌓는 데 집중하세요. 급소를 맞히면 피오라가 (P)\'치명적인 검무\'로 회복하며 빠르게 움직이니 방향을 계속 바꿔주세요.', lv3: '피오라의 (W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내고 기절을 걸 수 있으니 (Q)\'혹한의 맹습\'이나 (E)\'만년 서리\'를 쓰기 전에 먼저 확인하세요. (W)\'응수\'를 빼낸 뒤에 (Q)\'혹한의 맹습\'으로 진입해 (W)\'혹한의 서릿발\'을 적중시켜 서리 중첩을 빠르게 쌓으세요. 중첩이 쌓였을 때 (E)\'만년 서리\'를 사용해 피오라를 기절시키는 구도를 만드세요.', lv6: '피오라가 (R)\'대결투\'로 급소를 드러내면 이동 속도가 늘어나 따라붙으니 빠르게 거리를 조절하세요. (R)\'빙하 감옥\'으로 피오라를 먼저 기절시키면 정글러와 함께 킬을 노리기 좋아요. 피오라가 급소를 다 맞히면 주변 아군을 치유하니 딜교환 후에는 라인을 밀고 뒤로 빠지세요.', item: '판금 장화와 가시 갑옷을 추천해요. 피오라의 기본 공격 피해를 줄이고 기본 공격에 맞았을 때 반사 피해를 입히세요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거가 (Q)\'H-28 G 진화형 포탑\'을 설치해 구역을 장악하며 견제해요. 1~2레벨에는 포탑의 사거리 밖에서 막타만 챙기며 체력을 보존하세요. 포탑이 없는 빈틈에 짧게 평타를 섞어 (P)\'혹한의 분노\' 서리 갑옷을 유지하며 버티세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 중앙에 맞으면 기절하니 측면으로 피해서 둔화만 맞으세요. (Q)\'혹한의 맹습\'으로 빠르게 진입해 (W)\'혹한의 서릿발\'과 평타로 서리 중첩을 쌓은 뒤 (E)\'만년 서리\'로 기절시키세요. (W)\'마법공학 초소형 로켓\'이 모이는 위치를 계속 움직이며 피하는 게 중요해요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰기 전의 틈을 노리세요. (R)\'빙하 감옥\'으로 멀리서 기절시킨 뒤 (Q)\'혹한의 맹습\'으로 진입해 빠르게 처리하세요. 포탑이 너무 많으면 진입이 힘드니 정글러를 불러 함께 포탑을 지우며 압박하세요.', item: '마법 저항력과 강인함으로 기절 시간을 줄여주는 헤르메스의 발걸음을 신으세요. 첫 코어 아이템으로는 마법 저항력을 높여 포탑 피해를 견디게 해주는 대자연의 힘을 추천해요.', spell: '점멸과 순간이동을 추천해요. 하이머딩거의 강력한 라인 푸시력을 막기 위해 순간이동으로 빠르게 복귀하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_sejuani);
if (typeof module !== 'undefined') module.exports = top_sejuani;
